// What a record is, on this side of the wire.
//
// A record is one org heading that stands for one thing - a person, a laptop,
// a playing card - identified by a RECORD property naming the collection it
// belongs to. The server reads its property drawer into fields that already
// know what they are, so everything here draws a contact and a guitar pedal
// with the same code and neither view has a list of property names in it.
//
// The format itself is documented in docs/records.org in the orgs repo.

export type RecordField = {
    Key: string;
    Name: string;
    Label: string;
    // "email" | "tel" | "url" | "social" | "date" | "image" | "postal" | "text"
    Kind: string;
    Value: string;
    // The value made actionable, or "" when it is only text.
    Link: string;
    // Which network a social field is: "linkedin". "" for anything else.
    Network: string;
};

export type RecordChange = {
    When: string;
    What: string;
    // "added" | "updated" | "renamed" | "noted"
    Kind: string;
};

export type OrgRecord = {
    Hash: string;
    Id: string;
    Type: string;
    Name: string;
    Filename: string;
    LineNum: number;
    Tags: string[] | null;
    Fields: RecordField[] | null;
    Props: Record<string, string> | null;
    Notes: string;
    Image: string;
    Added: string;
    Updated: string;
    History: RecordChange[] | null;
};

export type RecordCollection = {
    Type: string;
    Name: string;
    Icon: string;
    Fields: string[] | null;
    Hash: string;
    Filename: string;
    LineNum: number;
    Count: number;
};

export type RecordFieldUse = {
    Key: string;
    Name: string;
    Label: string;
    Kind: string;
    Count: number;
};

export type BirthdayEvent = {
    Hash: string;
    Name: string;
    Type: string;
    Filename: string;
    LineNum: number;
    Date: string;
    Birthday: string;
    Age: number;
    Field: string;
    Image: string;
};

// ── Reading a field ──────────────────────────────────────────────────────────

// What to call a field on screen. "PHONE_MOBILE" is a phone number labelled
// mobile, and "phone · mobile" is how a person would say that.
export function fieldLabel(f: { Name: string; Label: string }): string {
    const name = f.Name.toLowerCase();
    if (!f.Label) return name;
    return `${name} · ${f.Label.toLowerCase()}`;
}

// The order the kinds are drawn in: the ones you reach for first. A kind with
// no entry sorts last, which is right for the odds and ends a collection of
// guitar pedals grows.
const KIND_ORDER: Record<string, number> = {
    tel: 1, email: 2, social: 3, url: 4, postal: 5, date: 6, text: 7, image: 9,
};

export function sortFields(fields: RecordField[]): RecordField[] {
    return [...fields].sort((a, b) => (KIND_ORDER[a.Kind] ?? 8) - (KIND_ORDER[b.Kind] ?? 8));
}

// The one value a list row has room for. A contact with three numbers shows
// the mobile, because that is the one anybody would ring.
export function firstOfKind(rec: OrgRecord, kind: string): RecordField | null {
    const fields = rec.Fields || [];
    let best: RecordField | null = null;
    for (const f of fields) {
        if (f.Kind !== kind) continue;
        if (!best) best = f;
        if (kind === 'tel' && (f.Label === 'MOBILE' || f.Name === 'MOBILE' || f.Name === 'CELL')) return f;
        if (kind === 'email' && f.Label === '') return f;
    }
    return best;
}

// The picture to draw for a record, or "" for one with none.
export function recordImage(rec: OrgRecord): string {
    if (rec.Image) return rec.Image;
    const f = (rec.Fields || []).find(f => f.Kind === 'image' && f.Link);
    return f ? f.Link : '';
}

// Initials for the fallback avatar. Two letters at most, and a name written in
// a script with no case still gives its first character back.
export function initialsOf(name: string): string {
    const words = name.trim().split(/\s+/).filter(Boolean);
    if (words.length === 0) return '?';
    if (words.length === 1) return words[0].slice(0, 2).toUpperCase();
    return (words[0][0] + words[words.length - 1][0]).toUpperCase();
}

// A stable colour per record, so the same person is the same colour every time
// the tab is opened. Hashed from the name rather than the index, which would
// change every time the list is filtered.
const AVATAR_HUES = [210, 340, 28, 160, 265, 190, 45, 310, 130, 0];
export function avatarHue(name: string): number {
    let h = 0;
    for (let i = 0; i < name.length; i++) h = (h * 31 + name.charCodeAt(i)) >>> 0;
    return AVATAR_HUES[h % AVATAR_HUES.length];
}

// ── Dates ────────────────────────────────────────────────────────────────────

// The three ways a record is allowed to write a yearly date, which the server
// also parses: an ISO date, the same inside an org timestamp, and vCard's
// year-less form for a birthday whose year nobody knows.
export function parseYearly(value: string): { month: number; day: number; year: number } | null {
    const v = (value || '').trim();
    let m = /^-{1,2}(\d{2})-(\d{2})$/.exec(v);
    if (m) return { month: +m[1], day: +m[2], year: 0 };
    m = /(\d{4})-(\d{2})-(\d{2})/.exec(v);
    if (m) return { year: +m[1], month: +m[2], day: +m[3] };
    m = /^(\d{1,2})\/(\d{1,2})\/(\d{4})$/.exec(v);
    if (m) return { month: +m[1], day: +m[2], year: +m[3] };
    return null;
}

const MONTHS = ['January', 'February', 'March', 'April', 'May', 'June',
    'July', 'August', 'September', 'October', 'November', 'December'];

// A yearly date written the way somebody says one. The year is left off when
// the record does not give one, rather than being guessed at.
export function yearlyText(value: string): string {
    const p = parseYearly(value);
    if (!p) return value;
    const day = `${MONTHS[p.month - 1]} ${p.day}`;
    return p.year ? `${day}, ${p.year}` : day;
}

// How long until the next one comes round, and what number it will be. Used
// for the birthday chip on a contact card.
export function nextYearly(value: string, from: Date = new Date()): { date: Date; days: number; age: number } | null {
    const p = parseYearly(value);
    if (!p) return null;
    const today = new Date(from.getFullYear(), from.getMonth(), from.getDate());
    let when = new Date(today.getFullYear(), p.month - 1, p.day);
    // A 29 February in a year that has none rolls into March; pull it back to
    // the 28th, which is where it is kept.
    if (when.getMonth() !== p.month - 1) when = new Date(today.getFullYear(), p.month, 0);
    if (when < today) {
        when = new Date(today.getFullYear() + 1, p.month - 1, p.day);
        if (when.getMonth() !== p.month - 1) when = new Date(today.getFullYear() + 1, p.month, 0);
    }
    const days = Math.round((when.getTime() - today.getTime()) / 86400000);
    const age = p.year ? when.getFullYear() - p.year : 0;
    return { date: when, days, age };
}

export function daysAwayText(days: number): string {
    if (days === 0) return 'today';
    if (days === 1) return 'tomorrow';
    if (days < 31) return `in ${days} days`;
    const months = Math.round(days / 30);
    return months <= 1 ? 'in a month' : `in ${months} months`;
}

// The date fields that are a yearly occasion rather than just a date: the ones
// worth counting down to and the ones the agenda puts a cake on. It is the
// same set the server builds /records/birthdays from (birthdayFields in
// records.go) and the two have to agree - a date the agenda shows and the card
// does not is the app disagreeing with itself.
//
// A BOUGHT_DATE is a date. It is not an occasion, and "turns 3 in 5 months"
// about a laptop is the view being clever at the reader's expense.
const CELEBRATIONS = new Set(['BIRTHDAY', 'BIRTHDATE', 'DOB', 'ANNIVERSARY']);

export function isCelebration(name: string): boolean {
    return CELEBRATIONS.has((name || '').toUpperCase());
}

// ── Writing a field ──────────────────────────────────────────────────────────

// A property name somebody typed, made into one org will take. Spaces become
// underscores and the case is normalised, so "phone mobile" and "Phone_Mobile"
// are the same field.
export function normaliseKey(key: string): string {
    return key.trim().toUpperCase().replace(/\s+/g, '_').replace(/[^A-Z0-9_+-]/g, '');
}

// What the server would call this key, worked out here so an add form can show
// the right input before anything has been saved. The rules are the ones in
// records.go and the two have to agree - change one and change both.
const KIND_SUFFIX: Record<string, string> = {
    DATE: 'date', URL: 'url', LINK: 'url', IMAGE: 'image', PHOTO: 'image',
};
const EMAIL_NAMES = new Set(['EMAIL', 'MAIL', 'E-MAIL']);
const TEL_NAMES = new Set(['PHONE', 'MOBILE', 'CELL', 'TEL', 'FAX', 'TELEPHONE']);
const POSTAL_NAMES = new Set(['ADDRESS', 'ADDR']);
const URL_NAMES = new Set(['URL', 'WEBSITE', 'WEB', 'HOMEPAGE', 'LINK', 'BLOG', 'SITE']);
const DATE_NAMES = new Set(['BIRTHDAY', 'BIRTHDATE', 'DOB', 'ANNIVERSARY', 'DATE']);
const IMAGE_NAMES = new Set(['IMAGE', 'PHOTO', 'AVATAR', 'PORTRAIT', 'PICTURE', 'LOGO', 'THUMBNAIL']);
export const SOCIAL_NAMES = new Set([
    'LINKEDIN', 'FACEBOOK', 'TWITTER', 'X', 'INSTAGRAM', 'MASTODON', 'GITHUB',
    'GITLAB', 'BLUESKY', 'YOUTUBE', 'TIKTOK', 'REDDIT', 'TELEGRAM', 'SIGNAL',
    'WHATSAPP', 'DISCORD', 'SLACK', 'MATRIX', 'THREADS', 'SNAPCHAT',
    'PINTEREST', 'TWITCH', 'SOUNDCLOUD', 'SPOTIFY', 'STRAVA', 'GOODREADS', 'KEYBASE',
]);

export function kindOfKey(key: string): { name: string; label: string; kind: string } {
    const up = normaliseKey(key);
    const cut = up.lastIndexOf('_');
    if (cut > 0 && KIND_SUFFIX[up.slice(cut + 1)]) {
        return { name: up.slice(0, cut).replace(/_/g, ' '), label: '', kind: KIND_SUFFIX[up.slice(cut + 1)] };
    }
    const i = up.indexOf('_');
    const name = i > 0 ? up.slice(0, i) : up;
    const label = i > 0 ? up.slice(i + 1).replace(/_/g, ' ') : '';
    let kind = 'text';
    if (EMAIL_NAMES.has(name)) kind = 'email';
    else if (TEL_NAMES.has(name)) kind = 'tel';
    else if (POSTAL_NAMES.has(name)) kind = 'postal';
    else if (URL_NAMES.has(name)) kind = 'url';
    else if (SOCIAL_NAMES.has(name)) kind = 'social';
    else if (DATE_NAMES.has(name) || name.endsWith('DATE') || name.startsWith('DATE')) kind = 'date';
    else if (IMAGE_NAMES.has(name)) kind = 'image';
    return { name, label, kind };
}

// What to put in an <input type=...> for a kind, so a phone number gets a
// keypad on a phone and a date gets a picker.
export function inputTypeFor(kind: string): string {
    switch (kind) {
        case 'email': return 'email';
        case 'tel': return 'tel';
        case 'url': return 'url';
        default: return 'text';
    }
}
