function OrgCheckboxHeading({records, selected, setSelected}: {records: any, selected: readonly string[], setSelected: React.Dispatch<React.SetStateAction<readonly string[]>>}) {
  return (
    <th style={{ width: 48, textAlign: 'center', padding: '12px 6px' }}>
      <Checkbox
        key="All"
        size="sm"
        indeterminate={
          records && selected.length > 0 && selected.length !== records.length
        }
        checked={records && selected && selected.length === records.length}
        onChange={(event) => {
          if (records) {
            setSelected(
              event.target.checked ? records.map((row: any) => row.Hash) : [],
            );
          }
        }}
        color={
          records && (selected.length > 0 || selected.length === records.length)
            ? 'primary'
            : undefined
        }
        sx={{ verticalAlign: 'text-bottom' }}
      />
    </th>
  );
}

