function propsTooltipContent(props: Record<string, string>): React.ReactNode {
  const entries = Object.entries(props);
  if (entries.length === 0) return 'No properties';
  return (
    <Box sx={{ display: 'flex', flexDirection: 'column', gap: 0.25, py: 0.5 }}>
      {entries.map(([k, v]) => (
        <Typography key={k} level="body-xs" sx={{ fontFamily: 'monospace', fontSize: '11px' }}>
          <strong>{k}:</strong> {v}
        </Typography>
      ))}
    </Box>
  );
}

// Four cells of this table are edited in place - the keyword, the date, the
// tags and the properties - and each opens its panel under the cell that was
// clicked rather than in a dialog in the middle of the window. Changing one of
// these is something you do to a row and then to the row under it, and a
// lightbox makes that a trip across the desk every time.
//
// One rule holds them together: **a cell that opens a panel must not stop the
// click from propagating.** A row has no click handler of its own here, so
// there is nothing to guard against - and the panels close themselves through a
// ClickAwayListener, which listens on the *document*. Calling stopPropagation
// keeps the native event from ever reaching it, so opening one panel leaves the
// last one still on screen and the table ends up wearing two.
//
// The properties, and the editor that changes them.
//
// Like the keyword above it, this opens under the cell rather than in the middle
// of the window. It is a popper rather than a Menu because what is in it is a
// form: a Menu moves the focus with the arrow keys and answers to typing, which
// is exactly wrong over a row of text fields.
//
// The values being edited are held here rather than on the row, because a query
// that re-runs every few seconds hands back a fresh row while somebody is still
// typing into it. What is on the server is written on blur, and the row is
// brought up to date by the handler that writes it.
// A row cell, which is a table cell in the table and a plain box in a card.
//
// The search results are a table on a wide screen and a list of cards on a
// phone, and the two are the *same* controls: the keyword dropdown, the tag
// panel, the date panel, the property panel and the row menu all behave
// identically in both. That is what `bare` is for. Writing a second set of
// controls for the card would mean every fix to an affordance had to be made
// twice, and the pair would come apart within a month - which is exactly what
// the table and the kanban list already avoid by being two layouts over one
// model rather than two views.
//
// A `<td>` outside a table is not a thing the browser is obliged to lay out
// sensibly, so this really does have to swap the element rather than restyle
// it.
function Cell({ bare, children, ...rest }: { bare?: boolean, children?: React.ReactNode } & React.HTMLAttributes<HTMLElement>) {
  if (bare) return <Box {...(rest as any)}>{children}</Box>;
  return <td {...rest}>{children}</td>;
}

function OrgProps({bare, row, onPropSet, onPropRemove}: {
  row: any,
  onPropSet?: (row: any, name: string, value: string) => void,
  onPropRemove?: (row: any, name: string) => void,
  bare?: boolean}) {
  const props: Record<string, string> = row.Props || {};
  const keys = Object.keys(props);
  const count = keys.length;

  const [open, setOpen] = React.useState(false);
  const [anchor, setAnchor] = React.useState<HTMLElement | null>(null);
  const [draft, setDraft] = React.useState<Record<string, string>>({});
  const [newName, setNewName] = React.useState('');
  const [newValue, setNewValue] = React.useState('');

  const show = (e: React.MouseEvent<HTMLElement>) => {
    setAnchor(e.currentTarget);
    // Opened on what the heading says now, so a value changed elsewhere is not
    // written back over from a stale draft.
    setDraft({ ...props });
    setNewName('');
    setNewValue('');
    setOpen(true);
  };

  const close = React.useCallback(() => {
    setOpen(false);
    setNewName('');
    setNewValue('');
  }, []);

  // Escape shuts it. On the document rather than on the panel, because the
  // panel is in a portal and the key is pressed in whichever field is being
  // typed into - which is not always inside it once a value has been committed.
  React.useEffect(() => {
    if (!open) return;
    const onKey = (e: KeyboardEvent) => { if (e.key === 'Escape') close(); };
    document.addEventListener('keydown', onKey);
    return () => document.removeEventListener('keydown', onKey);
  }, [open, close]);

  const commit = (name: string) => {
    const value = draft[name] ?? '';
    if (value !== (props[name] ?? '')) onPropSet?.(row, name, value);
  };

  const add = () => {
    const name = newName.trim();
    if (!name) return;
    onPropSet?.(row, name, newValue.trim());
    setDraft(prev => ({ ...prev, [name]: newValue.trim() }));
    setNewName('');
    setNewValue('');
  };

  let label: React.ReactNode;
  if (count === 0) {
    label = <Typography level="body-xs" sx={{ color: 'text.tertiary', fontStyle: 'italic' }}>+ prop</Typography>;
  } else if (count === 1) {
    label = <Typography level="body-xs">{keys[0]}</Typography>;
  } else {
    label = <Typography level="body-xs">{count} props</Typography>;
  }

  const draftKeys = Object.keys(draft);

  return (
    <Cell bare={bare}>
      {/* The tooltip is what the cell says at a glance, and it would sit over
          the editor it opened, so it is only offered while that is shut. */}
      <Tooltip
        title={open ? '' : propsTooltipContent(props)}
        variant="outlined"
        placement="top"
        arrow
      >
        <Box
          onClick={show}
          sx={{
            cursor: 'pointer', borderRadius: 'sm', px: 0.5, mx: -0.5,
            '&:hover': { opacity: 0.7 },
            ...(open ? { bgcolor: 'background.level2', opacity: 1 } : {}),
          }}
        >
          {label}
        </Box>
      </Tooltip>
      <Popper
        open={open}
        anchorEl={anchor}
        // Hung off the right edge of the cell rather than the left, so it opens
        // back over the table it came from. The properties are the last column
        // but one, and a panel this wide started at the cell would spend most
        // of itself off the side of the window.
        placement="bottom-end"
        modifiers={[
          { name: 'offset', options: { offset: [0, 6] } },
          // Kept on screen rather than running off the bottom of a long table.
          { name: 'preventOverflow', options: { padding: 8, altAxis: true } },
          { name: 'flip', options: { padding: 8 } },
        ]}
        style={{ zIndex: 1300 }}
      >
        <ClickAwayListener onClickAway={close}>
          <Sheet
            variant="outlined"
            sx={{
              borderRadius: 'md', boxShadow: 'lg', p: 1.25,
              minWidth: 320, maxWidth: 440, maxHeight: 340, overflowY: 'auto',
            }}
          >
            {draftKeys.length > 0 ? (
              <Box sx={{ display: 'flex', flexDirection: 'column', gap: 0.75, mb: 1 }}>
                {draftKeys.map(key => (
                  <Box key={key} sx={{ display: 'flex', gap: 0.75, alignItems: 'center' }}>
                    <Typography
                      level="body-xs"
                      sx={{
                        fontFamily: 'monospace', fontWeight: 'lg', minWidth: 76, maxWidth: 110,
                        flexShrink: 0, overflow: 'hidden', textOverflow: 'ellipsis', whiteSpace: 'nowrap',
                      }}
                      title={key}
                    >
                      {key}
                    </Typography>
                    <Input
                      size="sm"
                      value={draft[key]}
                      onChange={e => setDraft(prev => ({ ...prev, [key]: e.target.value }))}
                      onBlur={() => commit(key)}
                      onKeyDown={e => {
                        if (e.key === 'Enter') (e.target as HTMLInputElement).blur();
                      }}
                      sx={{ flex: 1 }}
                    />
                    <IconButton
                      size="sm"
                      variant="plain"
                      color="danger"
                      title={`Remove ${key}`}
                      onClick={() => {
                        onPropRemove?.(row, key);
                        setDraft(prev => {
                          const next = { ...prev };
                          delete next[key];
                          return next;
                        });
                      }}
                    >
                      <Typography sx={{ fontSize: '16px', lineHeight: 1 }}>&times;</Typography>
                    </IconButton>
                  </Box>
                ))}
              </Box>
            ) : (
              <Typography level="body-xs" sx={{ color: 'text.tertiary', fontStyle: 'italic', mb: 1 }}>
                No properties yet
              </Typography>
            )}
            <Divider sx={{ mb: 1 }} />
            <Box sx={{ display: 'flex', gap: 0.75 }}>
              <Input
                size="sm"
                placeholder="Name"
                // The cell is clicked to add one as often as to change one, and
                // on a heading with none that is the only thing it can be for.
                autoFocus={draftKeys.length === 0}
                value={newName}
                onChange={e => setNewName(e.target.value)}
                onKeyDown={e => { if (e.key === 'Enter') add(); }}
                sx={{ flex: 1 }}
              />
              <Input
                size="sm"
                placeholder="Value"
                value={newValue}
                onChange={e => setNewValue(e.target.value)}
                onKeyDown={e => { if (e.key === 'Enter') add(); }}
                sx={{ flex: 1 }}
              />
              <Button size="sm" onClick={add} disabled={!newName.trim()}>Add</Button>
            </Box>
          </Sheet>
        </ClickAwayListener>
      </Popper>
    </Cell>
  );
}

// The four planning lines a heading can carry a date on. The names are org's
// own; the labels are what a person calls them.
const DATE_KINDS: {name: string, label: string}[] = [
  { name: 'TIMESTAMP', label: 'On' },
  { name: 'SCHEDULED', label: 'Scheduled' },
  { name: 'DEADLINE', label: 'Deadline' },
  { name: 'CLOSED', label: 'Closed' },
];

// The date, and the panel that changes it - under the cell, like the keyword
// and the properties beside it.
//
// The date and the time are held here while they are being picked, because
// neither is a write on its own: a date with no kind is meaningless and a time
// with no date is nothing at all, so the three are sent together when Save is
// pressed. Which is also why this one keeps a button where the others commit as
// you go.
function OrgDateCell({bare, row, onDateSet, onDateRemove}: {
  row: any,
  onDateSet?: (row: any, name: string, date: string, time: string) => void,
  onDateRemove?: (row: any, name: string) => void,
  bare?: boolean}) {
  const has = !!(row?.Date?.Start) && !String(row.Date.Start).startsWith('0001-01-01');
  const date = has
    ? new Date(row.Date.Start).toLocaleDateString('en-us', { year: 'numeric', day: 'numeric', month: 'short' })
    : '';

  const [open, setOpen] = React.useState(false);
  const [anchor, setAnchor] = React.useState<HTMLElement | null>(null);
  const [kind, setKind] = React.useState('TIMESTAMP');
  const [value, setValue] = React.useState('');
  const [time, setTime] = React.useState('');

  const show = (e: React.MouseEvent<HTMLElement>) => {
    setAnchor(e.currentTarget);
    // Opened on the date the heading has now, so Save on an untouched panel
    // writes back what was already there rather than clearing it.
    if (has) {
      const d = new Date(row.Date.Start);
      const pad = (n: number) => String(n).padStart(2, '0');
      setValue(`${d.getFullYear()}-${pad(d.getMonth() + 1)}-${pad(d.getDate())}`);
      const hh = pad(d.getHours());
      const mm = pad(d.getMinutes());
      setTime(hh !== '00' || mm !== '00' ? `${hh}:${mm}` : '');
    } else {
      setValue('');
      setTime('');
    }
    setKind('TIMESTAMP');
    setOpen(true);
  };

  const close = React.useCallback(() => setOpen(false), []);

  React.useEffect(() => {
    if (!open) return;
    const onKey = (e: KeyboardEvent) => { if (e.key === 'Escape') close(); };
    document.addEventListener('keydown', onKey);
    return () => document.removeEventListener('keydown', onKey);
  }, [open, close]);

  const fieldStyle: React.CSSProperties = {
    padding: '6px 8px', borderRadius: 6, fontSize: '0.8125rem', width: '100%',
    border: '1px solid var(--joy-palette-neutral-outlinedBorder)',
    background: 'var(--joy-palette-background-surface)',
    color: 'var(--joy-palette-text-primary)',
    // Without this the browser draws its own picker in light paint over a dark
    // panel, calendar and all.
    colorScheme: 'light dark',
  };

  return (
    <Cell bare={bare}>
      <Box
        onClick={show}
        sx={{
          cursor: 'pointer', borderRadius: 'sm', px: 0.5, mx: -0.5,
          '&:hover': { opacity: 0.7 },
          ...(open ? { bgcolor: 'background.level2', opacity: 1 } : {}),
        }}
      >
        <Typography level="body-xs">
          {date || <span style={{ color: 'var(--joy-palette-text-tertiary)', fontStyle: 'italic' }}>+ date</span>}
        </Typography>
      </Box>
      <Popper
        open={open}
        anchorEl={anchor}
        placement="bottom-start"
        modifiers={[
          { name: 'offset', options: { offset: [0, 6] } },
          { name: 'preventOverflow', options: { padding: 8, altAxis: true } },
          { name: 'flip', options: { padding: 8 } },
        ]}
        style={{ zIndex: 1300 }}
      >
        <ClickAwayListener onClickAway={close}>
          <Sheet
            variant="outlined"
            sx={{ borderRadius: 'md', boxShadow: 'lg', p: 1.25, width: 292 }}
          >
            <Box sx={{ display: 'flex', gap: 0.5, flexWrap: 'wrap', mb: 1 }}>
              {DATE_KINDS.map(k => (
                <Chip
                  key={k.name}
                  size="sm"
                  variant={kind === k.name ? 'solid' : 'soft'}
                  color={kind === k.name ? 'primary' : 'neutral'}
                  onClick={() => setKind(k.name)}
                  sx={{ cursor: 'pointer' }}
                >
                  {k.label}
                </Chip>
              ))}
            </Box>
            <Box sx={{ display: 'flex', gap: 0.75, mb: 1.25 }}>
              <input
                type="date"
                autoFocus
                value={value}
                onChange={e => setValue(e.target.value)}
                style={{ ...fieldStyle, flex: '1 1 60%' }}
              />
              <input
                type="time"
                value={time}
                onChange={e => setTime(e.target.value)}
                style={{ ...fieldStyle, flex: '1 1 40%' }}
              />
            </Box>
            <Box sx={{ display: 'flex', gap: 0.75 }}>
              <Button
                size="sm"
                disabled={!value}
                onClick={() => { onDateSet?.(row, kind, value, time); close(); }}
                sx={{ flex: 1 }}
              >
                Save
              </Button>
              <Button
                size="sm"
                variant="soft"
                color="danger"
                onClick={() => { onDateRemove?.(row, kind); close(); }}
                sx={{ flex: 1 }}
              >
                Remove
              </Button>
            </Box>
          </Sheet>
        </ClickAwayListener>
      </Popper>
    </Cell>
  );
}

// The keyword, and the menu that changes it.
//
// The choices come up under the chip that was clicked. They used to come up in
// a dialog in the middle of the window, which is a trip across the desk for
// something you do to one row and then to the next one down. This is the same
// control the kanban list's rows use (StatusCell in KanbanList.tsx) and is
// meant to read the same way.
//
// What a heading may be set to is its own file's business - a file with its own
// `#+TODO:` line answers differently from the server's default - so the list is
// asked for rather than assumed. It is asked for when the menu opens rather
// than while the table is drawn: two hundred rows are two hundred requests
// nobody made.
function OrgState({bare, row, onStatusPick}: {row: any, onStatusPick?: (row: any, status: string) => void, bare?: boolean}) {
  const [states, setStates] = React.useState<string[] | null>(null);
  const asked = React.useRef(false);

  const load = React.useCallback(() => {
    if (asked.current) return;
    asked.current = true;
    Db.ODb.validStatus(row.Hash)
      .then(r => setStates([...(r.Active || []), ...(r.Done || [])]))
      .catch(() => setStates([]));
  }, [row.Hash]);

  // A row reused for another heading - a new page of results, a re-run query -
  // must not offer the keywords of the one before it.
  React.useEffect(() => { asked.current = false; setStates(null); }, [row.Hash]);

  const customSx = getStatusCustomSx(row.Status);
  const chip = row.Status
    ? (
      <Chip
        variant="soft"
        size="sm"
        // The chip is the picture and the button around it is the control, so
        // the chip itself must not take the click.
        sx={{ pointerEvents: 'none', ...(customSx || {}) }}
        startDecorator={getStatusIcon(row.Status)}
        color={getStatusColor(row.Status)}
      >
        {row.Status}
      </Chip>
    )
    : (
      <Chip
        variant="outlined"
        size="sm"
        color="neutral"
        sx={{
          pointerEvents: 'none', borderStyle: 'dashed',
          color: 'text.tertiary', fontStyle: 'italic',
        }}
      >
        + state
      </Chip>
    );

  return (
    <Cell bare={bare}>
      <Dropdown onOpenChange={(_e, open) => { if (open) load(); }}>
        <Tooltip
          size="sm"
          enterDelay={500}
          title={row.Status ? `${row.Status} — click to change the keyword` : 'No keyword — click to give this heading one'}
        >
          <MenuButton
            variant="plain"
            color="neutral"
            sx={{
              p: 0, minHeight: 0, minWidth: 0, border: 0, borderRadius: 'sm',
              background: 'transparent', maxWidth: '100%',
              '&:hover': { background: 'transparent' },
              '&:focus-visible': { outlineOffset: 2 },
            }}
          >
            {chip}
          </MenuButton>
        </Tooltip>
        <Menu
          size="sm"
          placement="bottom-start"
          sx={{ minWidth: 190, py: 0.5, zIndex: 1300 }}
        >
          {states === null ? (
            <MenuItem disabled>
              <CircularProgress size="sm" />
              <Typography level="body-xs" sx={{ color: 'text.tertiary' }}>
                Asking that file what it allows…
              </Typography>
            </MenuItem>
          ) : states.length === 0 ? (
            <MenuItem disabled>
              <Typography level="body-xs" sx={{ color: 'text.tertiary' }}>
                That file names no todo keywords.
              </Typography>
            </MenuItem>
          ) : states.map(sname => (
            <MenuItem
              key={sname}
              selected={sname === row.Status}
              onClick={() => { if (sname !== row.Status) onStatusPick?.(row, sname); }}
            >
              <Chip
                size="sm"
                variant={sname === row.Status ? 'solid' : 'soft'}
                color={getStatusColor(sname)}
                startDecorator={getStatusIcon(sname)}
                sx={{
                  pointerEvents: 'none',
                  ...(sname === row.Status ? {} : (getStatusCustomSx(sname) || {})),
                }}
              >
                {sname}
              </Chip>
            </MenuItem>
          ))}
        </Menu>
      </Dropdown>
    </Cell>
  );
}

function OrgHeadline({bare, row, isEditing, showFile, onCommit, onCancel, onStartEdit, clockedInKey, clockStartTime, clockKeyForRow}: {row: any, isEditing: boolean, showFile?: boolean, onCommit: (value: string) => void, onCancel: () => void, onStartEdit: (row: any) => void, clockedInKey?: string | null, clockStartTime?: string | null, clockKeyForRow?: (row: any) => string, bare?: boolean}) {
  const inputRef = React.useRef<HTMLInputElement>(null);
  const blurTimeoutRef = React.useRef<ReturnType<typeof setTimeout> | null>(null);
  const committedRef = React.useRef(false);
  const [localValue, setLocalValue] = React.useState(row.Headline);
  const [logbook, setLogbook] = React.useState<Array<{start: string, end: string, mins: number}> | null>(null);
  const logbookFetchedRef = React.useRef<string | null>(null);
  // Hovering the headline reads the heading. Nothing is fetched until the
  // popup is actually open, because a page of rows hovered on the way to a
  // button would otherwise be a page of requests.
  const [peeking, setPeeking] = React.useState(false);
  const theme = useHtmlTheme();
  const preview = useNodeContent(row, peeking, theme);

  const fetchLogbook = () => {
    if (logbookFetchedRef.current === row.Hash) return;
    logbookFetchedRef.current = row.Hash;
    Db.ODb.getLogbook(row.Hash).then((data) => {
      if (data && !Array.isArray(data) && data.entries) {
        setLogbook(data.entries.slice(0, 10));
      } else {
        setLogbook([]);
      }
    }).catch(() => setLogbook([]));
  };

  React.useEffect(() => {
    if (isEditing) {
      setLocalValue(row.Headline);
      committedRef.current = false;
      const t = setTimeout(() => {
        if (inputRef.current) {
          inputRef.current.focus();
          inputRef.current.select();
        }
      }, 50);
      return () => clearTimeout(t);
    }
  }, [isEditing]);

  React.useEffect(() => {
    return () => {
      if (blurTimeoutRef.current) clearTimeout(blurTimeoutRef.current);
    };
  }, []);

  const handleBlur = () => {
    blurTimeoutRef.current = setTimeout(() => {
      if (!committedRef.current) {
        committedRef.current = true;
        onCancel();
      }
    }, 150);
  };

  const handleKeyDown = (e: React.KeyboardEvent) => {
    if (e.key === 'Enter') {
      e.preventDefault();
      if (!committedRef.current) {
        committedRef.current = true;
        if (blurTimeoutRef.current) clearTimeout(blurTimeoutRef.current);
        onCommit(localValue);
      }
    }
    if (e.key === 'Escape') {
      e.preventDefault();
      if (!committedRef.current) {
        committedRef.current = true;
        if (blurTimeoutRef.current) clearTimeout(blurTimeoutRef.current);
        onCancel();
      }
    }
  };

  return (
    <Cell bare={bare}>
      <Box
        sx={{ display: 'flex', gap: 2, alignItems: 'center' }}
        onContextMenu={(e) => { e.preventDefault(); onStartEdit(row); }}
      >
        {isEditing ? (
          <input
            ref={inputRef}
            value={localValue}
            onChange={(e) => setLocalValue(e.target.value)}
            onKeyDown={handleKeyDown}
            onBlur={handleBlur}
            style={{ fontSize: '0.75rem', fontFamily: 'inherit', width: '100%', padding: '2px 4px', border: '1px solid var(--joy-palette-primary-outlinedBorder)', borderRadius: 4, outline: 'none' }}
          />
        ) : (
          <Tooltip
            variant="outlined"
            placement="right-start"
            arrow
            // Long enough that running the pointer down a page of rows opens
            // nothing, short enough that stopping on one feels like an answer.
            enterDelay={600}
            enterNextDelay={300}
            onOpen={() => { fetchLogbook(); setPeeking(true); }}
            onClose={() => setPeeking(false)}
            sx={{ maxWidth: 'min(560px, 90vw)', zIndex: 1250 }}
            title={
              <Box sx={{ display: 'flex', flexDirection: 'column', gap: 0.25, py: 0.5, maxWidth: 'min(540px, 88vw)', maxHeight: '70vh', overflowY: 'auto' }}>
                <Typography level="body-xs" sx={{ fontWeight: 'bold' }}>{row.Headline}</Typography>
                <Typography level="body-xs" sx={{ fontFamily: 'monospace', fontSize: '10px', color: 'text.tertiary' }}>
                  {row.Filename?.replace(/^.*\//, '')}:{row.LineNum}
                </Typography>
                {clockedInKey && clockKeyForRow && clockedInKey === clockKeyForRow(row) && clockStartTime && (
                  <Typography level="body-xs" sx={{ color: 'success.plainColor', fontSize: '10px' }}>
                    ⏱ Clocked in since {new Date(clockStartTime).toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' })}
                  </Typography>
                )}
                {logbook && logbook.length > 0 && (
                  <Box sx={{ mt: 0.5, borderTop: '1px solid', borderColor: 'divider', pt: 0.5 }}>
                    <Typography level="body-xs" sx={{ fontWeight: 'bold', fontSize: '10px', mb: 0.25 }}>Logbook</Typography>
                    {logbook.map((entry, i) => {
                      const start = new Date(entry.start);
                      const end = entry.end ? new Date(entry.end) : null;
                      const hrs = Math.floor(entry.mins / 60);
                      const mins = Math.round(entry.mins % 60);
                      const durStr = hrs > 0 ? `${hrs}h${mins > 0 ? ` ${mins}m` : ''}` : `${mins}m`;
                      const dateStr = start.toLocaleDateString([], { month: 'short', day: 'numeric' });
                      const timeStr = start.toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' });
                      const endStr = end ? end.toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' }) : '...';
                      return (
                        <Typography key={i} level="body-xs" sx={{ fontFamily: 'monospace', fontSize: '9px', color: 'text.secondary' }}>
                          {dateStr} {timeStr}–{endStr} ({durStr})
                        </Typography>
                      );
                    })}
                  </Box>
                )}
                {/* The heading itself, the same view the Inspect dialog
                    shows. It is the reason to hover at all, so it goes below
                    the meta rather than above it: the eye is already at the
                    top of the popup. */}
                <Box sx={{ mt: 0.75, borderTop: '1px solid', borderColor: 'divider', pt: 0.75 }}>
                  <NodeView content={preview} compact />
                </Box>
              </Box>
            }
          >
            <Typography level="body-xs" sx={{ cursor: 'default' }}>{row.Headline}</Typography>
          </Tooltip>
        )}
      </Box>
      {/* Where the heading lives, when it has been asked for. Outside the
          tooltip above rather than inside it: running the pointer along the
          filename should not open the preview popup, which is a big thing to
          have happen while you are reading a path. */}
      {showFile && !isEditing && row.Filename && (
        <Typography
          level="body-xs"
          title={`${row.Filename}:${(row.LineNum || 0) + 1}`}
          sx={{
            color: 'text.tertiary', fontFamily: 'monospace', fontSize: '10px',
            lineHeight: 1.4, mt: '1px', maxWidth: '100%',
            overflow: 'hidden', textOverflow: 'ellipsis', whiteSpace: 'nowrap',
          }}
        >
          {String(row.Filename).replace(/^.*\//, '')}:{(row.LineNum || 0) + 1}
        </Typography>
      )}
    </Cell>
  );
}

