function OrgEntry({key, row, selected, setSelected, showFile, onInspect, onJump, onEdit, onStatusPick, knownTags, onLoadTags, onToggleTag, onDateSet, onDateRemove, onDelete, onRename, onArchive, onMove, onClockIn, onClockOut, clockedInKey, clockStartTime, clockKeyForRow, isEditing, onRenameCommit, onRenameCancel, onStartEdit, onPropSet, onPropRemove}: {key: any, row: any, selected: readonly string[], setSelected: React.Dispatch<React.SetStateAction<readonly string[]>>, showFile?: boolean, onInspect?: (row: any) => void, onJump?: (row: any) => void, onEdit?: (row: any) => void, onStatusPick?: (row: any, status: string) => void, knownTags: string[], onLoadTags?: () => void, onToggleTag?: (row: any, tag: string) => void, onDateSet?: (row: any, name: string, date: string, time: string) => void, onDateRemove?: (row: any, name: string) => void, onDelete?: (row: any) => void, onRename?: (row: any) => void, onArchive?: (row: any) => void, onMove?: (row: any) => void, onClockIn?: (row: any) => void, onClockOut?: () => void, clockedInKey?: string | null, clockStartTime?: string | null, clockKeyForRow?: (row: any) => string, isEditing: boolean, onRenameCommit: (value: string) => void, onRenameCancel: () => void, onStartEdit: (row: any) => void, onPropSet?: (row: any, name: string, value: string) => void, onPropRemove?: (row: any, name: string) => void}) {
  var items = [
      <OrgCheckbox key={`${key}-1`} row={row} selected={selected} setSelected={setSelected}/>,
      <OrgHeadline key={`${key}-2`} row={row} isEditing={isEditing} showFile={showFile} onCommit={onRenameCommit} onCancel={onRenameCancel} onStartEdit={onStartEdit} clockedInKey={clockedInKey} clockStartTime={clockStartTime} clockKeyForRow={clockKeyForRow}/>,
      <OrgState    key={`${key}-3`} row={row} onStatusPick={onStatusPick}/>,
      <OrgDateCell key={`${key}-4`} row={row} onDateSet={onDateSet} onDateRemove={onDateRemove}/>,
      <OrgTags     key={`${key}-5`} row={row} knownTags={knownTags} onLoadTags={onLoadTags} onToggleTag={onToggleTag}/>,
      <OrgProps    key={`${key}-6`} row={row} onPropSet={onPropSet} onPropRemove={onPropRemove}/>,
      <OrgQuickMenu key={`${key}-7`} row={row} selected={selected} setSelected={setSelected} onInspect={onInspect} onJump={onJump} onEdit={onEdit} onDelete={onDelete} onRename={onRename} onArchive={onArchive} onMove={onMove} onClockIn={onClockIn} onClockOut={onClockOut} clockedInKey={clockedInKey} clockStartTime={clockStartTime} clockKeyForRow={clockKeyForRow}/>
  ];
  return (
    // The hash is on the row as well as being its key, because coming back from
    // the file has to find it again in the DOM - a key is React's handle on a
    // row, not the document's.
    <tr key={row.Hash} data-row-hash={row.Hash}>
      {items.map((i) => i)}
    </tr>
  );
}

