// One result, as a card.
//
// The phone layout for the results. It is not a cut-down table: every control a
// row has is here, and each of them is the *same component* the table cell uses,
// drawn with `bare` so it lays itself out as a box rather than as a table cell.
// A heading's keyword, tags, dates and properties are all still editable where
// they sit, which is the whole point of the row - a phone that could only read
// the results would be a worse thing than a table you have to scroll sideways.
//
// The one thing left out is the select checkbox. The bulk actions it feeds are
// a desktop job - pick thirty rows, change a tag on all of them - and a
// checkbox on every card costs a column of width on the screen that has least
// of it.
function OrgCard(props: any) {
  const { row, showFile } = props;
  return (
    <Sheet
      variant="outlined"
      // The hash goes on the card for the same reason it goes on the row:
      // coming back from the file has to find it again in the document, and a
      // React key is not something the document can be asked about.
      data-row-hash={row.Hash}
      sx={{
        borderRadius: 'sm',
        p: 1.25,
        display: 'flex',
        flexDirection: 'column',
        gap: 0.75,
        minWidth: 0,
      }}
    >
      {/* The keyword and the menu on one line, with the menu hard right: the
          two controls that are about the row rather than about its text. */}
      <Box sx={{ display: 'flex', alignItems: 'center', gap: 1, minWidth: 0 }}>
        <OrgState bare row={row} onStatusPick={props.onStatusPick} />
        <Box sx={{ flex: 1 }} />
        <OrgDateCell bare row={row} onDateSet={props.onDateSet} onDateRemove={props.onDateRemove} />
        <OrgQuickMenu
          bare
          row={row}
          selected={props.selected}
          setSelected={props.setSelected}
          onInspect={props.onInspect}
          onJump={props.onJump}
          onEdit={props.onEdit}
          onDelete={props.onDelete}
          onRename={props.onRename}
          onArchive={props.onArchive}
          onMove={props.onMove}
          onClockIn={props.onClockIn}
          onClockOut={props.onClockOut}
          clockedInKey={props.clockedInKey}
          clockStartTime={props.clockStartTime}
          clockKeyForRow={props.clockKeyForRow}
        />
      </Box>
      <OrgHeadline
        bare
        row={row}
        isEditing={props.isEditing}
        showFile={showFile}
        onCommit={props.onRenameCommit}
        onCancel={props.onRenameCancel}
        onStartEdit={props.onStartEdit}
        clockedInKey={props.clockedInKey}
        clockStartTime={props.clockStartTime}
        clockKeyForRow={props.clockKeyForRow}
      />
      <Box sx={{ display: 'flex', alignItems: 'center', gap: 1, flexWrap: 'wrap', minWidth: 0 }}>
        <OrgTags bare row={row} knownTags={props.knownTags} onLoadTags={props.onLoadTags} onToggleTag={props.onToggleTag} />
        <OrgProps bare row={row} onPropSet={props.onPropSet} onPropRemove={props.onPropRemove} />
      </Box>
    </Sheet>
  );
}

// The band that starts one file's results when the list is grouped.
//
// A row of the same table rather than a section of its own, because the
// columns have to keep lining up: a group of results is still the same list,
// read in a different order.
function FileGroup({ filename, count, folded, onFold, onOpen }: {
  filename: string;
  count: number;
  folded: boolean;
  onFold: () => void;
  onOpen: () => void;
}) {
  const base = filename.replace(/^.*\//, '') || 'no file';
  const dir = filename.slice(0, filename.length - base.length).replace(/\/$/, '');
  return (
    <tr>
      <td colSpan={7} style={{ padding: 0 }}>
        <Box
          onClick={onFold}
          sx={{
            display: 'flex', alignItems: 'center', gap: 1,
            px: 1, py: 0.75, cursor: 'pointer',
            bgcolor: 'background.level1',
            borderTop: '1px solid', borderColor: 'divider',
            '&:hover': { bgcolor: 'background.level2' },
          }}
        >
          <KeyboardArrowRightIcon
            sx={{
              fontSize: 16, color: 'text.tertiary', flexShrink: 0,
              transform: folded ? 'none' : 'rotate(90deg)',
              transition: 'transform 0.15s',
            }}
          />
          <Typography level="body-xs" sx={{ fontWeight: 'lg' }}>{base}</Typography>
          {dir !== '' && (
            <Typography
              level="body-xs"
              title={filename}
              sx={{
                color: 'text.tertiary', fontFamily: 'monospace', fontSize: '10px',
                overflow: 'hidden', textOverflow: 'ellipsis', whiteSpace: 'nowrap',
                direction: 'rtl', textAlign: 'left', maxWidth: 360,
              }}
            >
              {dir}
            </Typography>
          )}
          <Chip size="sm" variant="soft" color="neutral" sx={{ '--Chip-minHeight': '18px', fontSize: 10 }}>
            {count}
          </Chip>
          <Box sx={{ flex: 1 }} />
          <Tooltip size="sm" enterDelay={500} title={`Open ${base} in Files`}>
            <IconButton
              size="sm"
              variant="plain"
              color="neutral"
              onClick={e => { e.stopPropagation(); onOpen(); }}
              sx={{ '--IconButton-size': '24px' }}
            >
              <OpenInFileIcon sx={{ fontSize: 14 }} />
            </IconButton>
          </Tooltip>
        </Box>
      </td>
    </tr>
  );
}

function OrgEntryHeading({records, order, setOrder, selected, setSelected}: {records: any, order: any, setOrder:React.Dispatch<React.SetStateAction<Order>> , selected: readonly string[], setSelected: React.Dispatch<React.SetStateAction<readonly string[]>>}) {
  var headings = [
    <OrgCheckboxHeading key="1" records={records} selected={selected} setSelected={setSelected}/>,
    <OrgHeadlineHeading key="2" order={order} setOrder={setOrder}/>,
    <OrgStateHeading key="3" />,
    <OrgDateHeading key="4" />,
    <OrgTagsHeading key="5" />,
    <OrgPropsHeading key="6" />,
    <OrgQuickMenuHeading key="7" />
  ];
  return (
    <tr key="0" id="org-entry-heading">
      {headings.map((i) => i)}
    </tr>
  );
}
