export default function Search() {
  const isMobile = useIsMobile();
  const [order, setOrder] = React.useState<Order>('desc');
  const [selected, setSelected] = React.useState<readonly string[]>([]);
  const [open, setOpen] = React.useState(false);
  const [records, setRecords] = React.useState<any[]>([]);
  const [statusList, setStatusList] = React.useState<string[]>([]);
  const [tagsList, setTagsList] = React.useState<string[]>([]);
  const [activeStatus, setActiveStatus] = React.useState<string[]>([]);
  const [todoMode, setTodoMode] = React.useState<'isTodo' | 'noStatus' | 'anything' | 'projects'>('isTodo');
  const [activeTags, setActiveTags] = React.useState<string[]>([]);
  const [activeSearch, setActiveSearch] = React.useState<string>("");
  // What is in the query box right now, beside the query being run. They are
  // two things because the box is typed in and the query is debounced, and
  // auto-pairing has to put text back in the box immediately.
  const [searchText, setSearchText] = React.useState<string>("");
  // A regular expression over what is written under a heading as well as its
  // headline. Its own box rather than a mode on the first one: it is the
  // question "where did I write about this", which is usually asked *and* a
  // query, not instead of one.
  const [contentText, setContentText] = React.useState<string>("");
  const [activeContent, setActiveContent] = React.useState<string>("");
  const [propsList, setPropsList] = React.useState<string[]>([]);
  const [activeProps, setActiveProps] = React.useState<string[]>([]);
  const [currentPage, setCurrentPage] = React.useState(0);
  const pageSize = 25;

  // Clock state — server converts hash targets to file+olp, so we store filename+headline to match rows
  const [clockedInKey, setClockedInKey] = React.useState<string | null>(null);
  const [clockStartTime, setClockStartTime] = React.useState<string | null>(null);
  const clockLocalRef = React.useRef<boolean>(false);

  const clockKeyForRow = (row: any): string => `${row.Filename}::${row.Headline}`;

  const fetchClockState = React.useCallback(async () => {
    try {
      const state = await Db.ODb.getClockState();
      // If we clocked in locally, don't let the poll override our state
      if (clockLocalRef.current) return;
      // doGet returns [] on network error — ignore non-object responses
      if (!state || Array.isArray(state) || typeof state !== 'object') return;
      if (state.Active && state.Target) {
        // Server stores target as file+olp: Filename="/path/file.org", Id="Heading1::Heading2"
        const filename = state.Target.Filename || '';
        const olp = state.Target.Id || '';
        // The last segment of the outline path is the headline
        const headline = olp.split('::').pop() || '';
        const key = `${filename}::${headline}`;
        setClockedInKey(key);
        const serverTime = state.Time?.Start || null;
        if (serverTime) setClockStartTime(serverTime);
      } else {
        setClockedInKey(null);
        setClockStartTime(null);
      }
    } catch (e) {
      console.error('Failed to fetch clock state:', e);
    }
  }, []);

  React.useEffect(() => {
    fetchClockState();
    const interval = setInterval(fetchClockState, 30000);
    return () => clearInterval(interval);
  }, [fetchClockState]);

  const handleClockIn = React.useCallback(async (row: any) => {
    if (!row) return;
    try {
      await Db.ODb.clockIn(row.Hash);
      clockLocalRef.current = true;
      setClockedInKey(clockKeyForRow(row));
      setClockStartTime(new Date().toISOString());
    } catch (e) {
      console.error('Failed to clock in:', e);
    }
  }, []);

  const handleClockOut = React.useCallback(async () => {
    try {
      await Db.ODb.clockOut();
      clockLocalRef.current = false;
      setClockedInKey(null);
      setClockStartTime(null);
    } catch (e) {
      console.error('Failed to clock out:', e);
    }
  }, []);

  // Editor modal state
  const [editorOpen, setEditorOpen] = React.useState(false);
  const [editorRow, setEditorRow] = React.useState<any>(null);

  const handleEdit = React.useCallback((row: any) => {
    setEditorRow(row);
    setEditorOpen(true);
  }, []);

  const handleEditorMutate = React.useCallback((update: { hash: string; field: string; value: any }) => {
    setRecords(prev => prev.map(r => {
      if (r.Hash !== update.hash) return r;
      switch (update.field) {
        case 'headline': return { ...r, Headline: update.value };
        case 'status': return { ...r, Status: update.value };
        case 'tags': return { ...r, Tags: update.value };
        case 'props': return { ...r, Props: { ...r.Props, ...update.value } };
        default: return r;
      }
    }));
  }, []);

  // Inspect dialog. What is in it, and the requests that fill it, are
  // NodeView's - the hover popup shows exactly the same thing, and two copies
  // of it would have drifted apart the first time either was changed.
  const [inspectOpen, setInspectOpen] = React.useState(false);
  const [inspectRow, setInspectRow] = React.useState<any>(null);
  const htmlTheme = useHtmlTheme();
  // Whether the address book and the other collections are in these results.
  // Off by default - see withoutRecords in orgquery.ts for why.
  const [showRecords, setShowRecords] = useSetting('searchRecords');
  // Two ways of saying where a result came from: on every row, and as bands
  // over the list. Both are about reading rather than about what was found,
  // so both live in the browser.
  const [showFile, setShowFile] = useSetting('searchShowFile');
  const [groupByFile, setGroupByFile] = useSetting('searchGroupByFile');
  // Which files are folded shut. Not stored: it is about this reading of this
  // list, and a file folded last week quietly hiding its results today is not
  // what anybody meant by folding it.
  const [foldedFiles, setFoldedFiles] = React.useState<Set<string>>(new Set());
  React.useEffect(() => { if (!groupByFile) setFoldedFiles(new Set()); }, [groupByFile]);
  // Five seconds: the dialog is a window onto a file something else may be
  // writing, and a heading edited in the editor should catch up on its own.
  const inspectContent = useNodeContent(inspectRow, inspectOpen, htmlTheme, 5000);

  // Straight to where the heading lives. The Files tab is mounted by the
  // switch, so the jump is left for it rather than handed to it - see
  // NavContext.tsx.
  const nav = useNav();
  const handleJump = React.useCallback((row: any) => {
    if (!row || !row.Filename) return;
    nav.toFile({
      filename: row.Filename,
      heading: row.Headline || '',
      line: typeof row.LineNum === 'number' ? row.LineNum : undefined,
      // And the way back: the page of results this row was on, and the row
      // itself. A search is the one place where losing your place really
      // costs - three hundred headings deep and paged.
      back: {
        app: 'Search', label: 'Back to search',
        where: { tab: 'Search', hash: row.Hash, page: currentPage },
      },
    });
  }, [nav, currentPage]);

  const handleInspect = React.useCallback((row: any) => {
    setInspectRow(row);
    setInspectOpen(true);
  }, []);

  // The keyword a row was set to, from the menu under its chip. Which keywords
  // that menu offers is the cell's own business - it has to ask the heading's
  // own file - so all that reaches here is the one that was picked.
  const handleStatusPick = React.useCallback(async (row: any, newStatus: string) => {
    try {
      await Db.ODb.changeStatus(row.Hash, newStatus);
      // Update the row in local state
      setRecords(prev => prev.map(r => r.Hash === row.Hash ? { ...r, Status: newStatus } : r));
    } catch (e) {
      console.error('Failed to change status:', e);
    }
  }, []);

  // Every tag this database knows, for the panel under a tags cell to offer.
  // They are the same for every row, so they are asked for once and shared -
  // the panel asks when it opens, and every ask after the first is a no-op.
  const [allKnownTags, setAllKnownTags] = React.useState<string[]>([]);
  const askedTags = React.useRef(false);

  const loadAllTags = React.useCallback(async () => {
    if (askedTags.current) return;
    askedTags.current = true;
    try {
      const tags = await Db.ODb.getAllTags();
      if (Array.isArray(tags)) setAllKnownTags(tags);
    } catch (e) {
      console.error('Failed to fetch all tags:', e);
      // Asked and failed is still asked for this page; the next tag written
      // goes into the list below regardless, so the panel is never empty for
      // want of a retry nobody would see.
    }
  }, []);

  // Putting a tag on a heading and taking it off are the same call. A tag used
  // for the first time joins both lists, so it is offered on the next heading
  // and can be filtered on without a re-query.
  const handleToggleTag = React.useCallback(async (row: any, tag: string) => {
    try {
      await Db.ODb.toggleTag(row.Hash, tag);
      setRecords(prev => prev.map(r => {
        if (r.Hash !== row.Hash) return r;
        const had: string[] = r.Tags || [];
        return { ...r, Tags: had.includes(tag) ? had.filter(t => t !== tag) : [...had, tag] };
      }));
      setAllKnownTags(prev => prev.includes(tag) ? prev : [...prev, tag]);
      setTagsList(prev => prev.includes(tag) ? prev : [...prev, tag]);
    } catch (e) {
      console.error('Failed to toggle tag:', e);
    }
  }, []);

  // Inline rename state
  const [renameHash, setRenameHash] = React.useState<string | null>(null);

  const handleStartRename = React.useCallback((row: any) => {
    setRenameHash(row.Hash);
  }, []);

  const handleRenameCancel = React.useCallback(() => {
    setRenameHash(null);
  }, []);

  const handleRenameCommit = React.useCallback(async (value: string) => {
    if (!renameHash || !value.trim()) {
      setRenameHash(null);
      return;
    }
    const currentRow = records.find(r => r.Hash === renameHash);
    if (currentRow && value.trim() === currentRow.Headline) {
      setRenameHash(null);
      return;
    }
    try {
      await Db.ODb.renameHeadline(renameHash, value.trim());
      setRecords(prev => prev.map(r => r.Hash === renameHash ? { ...r, Headline: value.trim() } : r));
    } catch (e) {
      console.error('Failed to rename headline:', e);
    }
    setRenameHash(null);
  }, [renameHash, records]);

  // A property written, and one taken off. Adding one and changing one are the
  // same write - a property drawer has no notion of a property that is there but
  // has never been set - and an empty value is what the server reads as a
  // removal, drawer and all.
  const handlePropSet = React.useCallback(async (row: any, name: string, value: string) => {
    try {
      await Db.ODb.changeProperty(row.Hash, name, value);
      setRecords(prev => prev.map(r => r.Hash === row.Hash ? { ...r, Props: { ...r.Props, [name]: value } } : r));
    } catch (e) {
      console.error('Failed to change property:', e);
    }
  }, []);

  const handlePropRemove = React.useCallback(async (row: any, name: string) => {
    try {
      await Db.ODb.changeProperty(row.Hash, name, '');
      setRecords(prev => prev.map(r => {
        if (r.Hash !== row.Hash) return r;
        const updated = { ...r.Props };
        delete updated[name];
        return { ...r, Props: updated };
      }));
    } catch (e) {
      console.error('Failed to remove property:', e);
    }
  }, []);

  // The date a row was given, from the panel under its cell. The panel holds the
  // picking; this holds the writing.
  const handleDateSet = React.useCallback(async (row: any, name: string, newDate: string, time: string) => {
    if (!newDate) return;
    try {
      // Format as org timestamp: <YYYY-MM-DD Day> or <YYYY-MM-DD Day HH:MM>
      const d = new Date(newDate + 'T00:00:00');
      // A date field normally reports '' rather than nonsense, but it will hand
      // over a year outside what Date can hold. Caught here because the throw
      // is two lines further down, by which point `days[NaN]` has already put
      // `<101520-10-15 undefined>` in somebody's file.
      if (Number.isNaN(d.getTime())) return;
      const days = ['Sun', 'Mon', 'Tue', 'Wed', 'Thu', 'Fri', 'Sat'];
      const orgDate = time
        ? `<${newDate} ${days[d.getDay()]} ${time}>`
        : `<${newDate} ${days[d.getDay()]}>`;
      await Db.ODb.changeDate(row.Hash, name, orgDate);
      // Update local state with the new date
      const isoDate = time
        ? new Date(newDate + 'T' + time + ':00').toISOString()
        : d.toISOString();
      setRecords(prev => prev.map(r =>
        r.Hash === row.Hash ? { ...r, Date: { ...r.Date, Start: isoDate } } : r
      ));
    } catch (e) {
      console.error('Failed to change date:', e);
    }
  }, []);

  const handleDateRemove = React.useCallback(async (row: any, name: string) => {
    try {
      await Db.ODb.removeDate(row.Hash, name);
      setRecords(prev => prev.map(r =>
        r.Hash === row.Hash ? { ...r, Date: { ...r.Date, Start: '' } } : r
      ));
    } catch (e) {
      console.error('Failed to remove date:', e);
    }
  }, []);

  const handleDelete = React.useCallback(async (row: any) => {
    if (!row) return;
    try {
      await Db.ODb.deleteEntry(row.Hash);
      setRecords(prev => prev.filter(r => r.Hash !== row.Hash));
      setSelected(prev => prev.filter(id => id !== row.Hash));
    } catch (e) {
      console.error('Failed to delete entry:', e);
    }
  }, []);

  const handleArchive = React.useCallback(async (row: any) => {
    if (!row) return;
    try {
      await Db.ODb.archiveEntry(row.Hash);
      setRecords(prev => prev.filter(r => r.Hash !== row.Hash));
      setSelected(prev => prev.filter(id => id !== row.Hash));
    } catch (e) {
      console.error('Failed to archive entry:', e);
    }
  }, []);

  // Bulk date modal state
  const [bulkDateModalOpen, setBulkDateModalOpen] = React.useState(false);
  const [bulkDateValue, setBulkDateValue] = React.useState('');
  const [bulkDateTime, setBulkDateTime] = React.useState('');
  const [bulkDateName, setBulkDateName] = React.useState('TIMESTAMP');

  const handleBulkDateChange = React.useCallback(async () => {
    if (!bulkDateValue || selected.length === 0) return;
    const d = new Date(bulkDateValue + 'T00:00:00');
    const days = ['Sun', 'Mon', 'Tue', 'Wed', 'Thu', 'Fri', 'Sat'];
    const orgDate = bulkDateTime
      ? `<${bulkDateValue} ${days[d.getDay()]} ${bulkDateTime}>`
      : `<${bulkDateValue} ${days[d.getDay()]}>`;
    const isoDate = bulkDateTime
      ? new Date(bulkDateValue + 'T' + bulkDateTime + ':00').toISOString()
      : d.toISOString();
    try {
      await Promise.all(selected.map(hash => Db.ODb.changeDate(hash, bulkDateName, orgDate)));
      setRecords(prev => prev.map(r =>
        selected.includes(r.Hash) ? { ...r, Date: { ...r.Date, Start: isoDate } } : r
      ));
    } catch (e) {
      console.error('Failed to bulk change date:', e);
    }
    setBulkDateModalOpen(false);
    setBulkDateValue('');
    setBulkDateTime('');
  }, [selected, bulkDateValue, bulkDateTime, bulkDateName]);

  const handleBulkDateRemove = React.useCallback(async () => {
    if (selected.length === 0) return;
    try {
      await Promise.all(selected.map(hash => Db.ODb.removeDate(hash, bulkDateName)));
      setRecords(prev => prev.map(r =>
        selected.includes(r.Hash) ? { ...r, Date: { ...r.Date, Start: '' } } : r
      ));
    } catch (e) {
      console.error('Failed to bulk remove date:', e);
    }
    setBulkDateModalOpen(false);
  }, [selected, bulkDateName]);

  // Bulk tags modal state
  const [bulkTagModalOpen, setBulkTagModalOpen] = React.useState(false);
  const [bulkTagModalTags, setBulkTagModalTags] = React.useState<string[]>([]);
  const [newBulkTagInput, setNewBulkTagInput] = React.useState('');
  const [bulkAllKnownTags, setBulkAllKnownTags] = React.useState<string[]>([]);

  const fetchBulkTags = React.useCallback(async () => {
    try {
      const tags = await Db.ODb.getAllTags();
      if (Array.isArray(tags)) setBulkAllKnownTags(tags);
    } catch (e) {
      console.error('Failed to fetch tags:', e);
    }
  }, []);

  const handleBulkTagToggle = React.useCallback(async (tag: string) => {
    if (selected.length === 0) return;
    try {
      await Promise.all(selected.map(hash => Db.ODb.toggleTag(hash, tag)));
      // Update local records: toggle the tag on each selected row
      setRecords(prev => prev.map(r => {
        if (!selected.includes(r.Hash)) return r;
        const tags = r.Tags || [];
        const has = tags.includes(tag);
        return { ...r, Tags: has ? tags.filter((t: string) => t !== tag) : [...tags, tag] };
      }));
      setBulkTagModalTags(prev => prev.includes(tag) ? prev.filter(t => t !== tag) : [...prev, tag]);
    } catch (e) {
      console.error('Failed to bulk toggle tag:', e);
    }
  }, [selected]);

  const handleBulkAddNewTag = React.useCallback(async () => {
    const tag = newBulkTagInput.trim();
    if (!tag || selected.length === 0) return;
    try {
      await Promise.all(selected.map(hash => Db.ODb.toggleTag(hash, tag)));
      setRecords(prev => prev.map(r => {
        if (!selected.includes(r.Hash)) return r;
        const tags = r.Tags || [];
        return { ...r, Tags: tags.includes(tag) ? tags : [...tags, tag] };
      }));
      setBulkTagModalTags(prev => prev.includes(tag) ? prev : [...prev, tag]);
      if (!bulkAllKnownTags.includes(tag)) {
        setBulkAllKnownTags(prev => [...prev, tag]);
      }
      setNewBulkTagInput('');
    } catch (e) {
      console.error('Failed to bulk add tag:', e);
    }
  }, [selected, newBulkTagInput, bulkAllKnownTags]);

  // Bulk properties modal state
  const [bulkPropModalOpen, setBulkPropModalOpen] = React.useState(false);
  const [newBulkPropName, setNewBulkPropName] = React.useState('');
  const [newBulkPropValue, setNewBulkPropValue] = React.useState('');

  const handleBulkAddProp = React.useCallback(async () => {
    const name = newBulkPropName.trim();
    const value = newBulkPropValue.trim();
    if (!name || selected.length === 0) return;
    try {
      await Promise.all(selected.map(hash => Db.ODb.changeProperty(hash, name, value)));
      setRecords(prev => prev.map(r =>
        selected.includes(r.Hash) ? { ...r, Props: { ...r.Props, [name]: value } } : r
      ));
      setNewBulkPropName('');
      setNewBulkPropValue('');
    } catch (e) {
      console.error('Failed to bulk change property:', e);
    }
  }, [selected, newBulkPropName, newBulkPropValue]);

  const handleBulkRemoveProp = React.useCallback(async (name: string) => {
    if (selected.length === 0) return;
    try {
      await Promise.all(selected.map(hash => Db.ODb.changeProperty(hash, name, '')));
      setRecords(prev => prev.map(r => {
        if (!selected.includes(r.Hash)) return r;
        const updated = { ...r.Props };
        delete updated[name];
        return { ...r, Props: updated };
      }));
    } catch (e) {
      console.error('Failed to bulk remove property:', e);
    }
  }, [selected]);

  // Refile modal state
  const [refileModalOpen, setRefileModalOpen] = React.useState(false);
  const [refileModalRow, setRefileModalRow] = React.useState<any>(null);
  const [refileTargets, setRefileTargets] = React.useState<string[]>([]);
  const [refileDebouncedSearch, setRefileDebouncedSearch] = React.useState('');
  const [refileSelected, setRefileSelected] = React.useState<string | null>(null);
  const refileSearchTimerRef = React.useRef<ReturnType<typeof setTimeout> | null>(null);

  const handleRefileSearchChange = React.useCallback((e: React.ChangeEvent<HTMLInputElement>) => {
    const value = e.target.value;
    if (refileSearchTimerRef.current) clearTimeout(refileSearchTimerRef.current);
    refileSearchTimerRef.current = setTimeout(() => {
      setRefileDebouncedSearch(value);
      setRefileSelected(null);
    }, 150);
  }, []);

  const handleMoveClick = React.useCallback(async (row: any) => {
    setRefileModalRow(row);
    setRefileDebouncedSearch('');
    setRefileSelected(null);
    setRefileModalOpen(true);
    try {
      const targets = await Db.ODb.getRefileTargets();
      if (Array.isArray(targets)) {
        setRefileTargets(targets);
      }
    } catch (e) {
      console.error('Failed to fetch refile targets:', e);
    }
  }, []);

  const refileFiltered = React.useMemo(() => {
    if (!refileDebouncedSearch.trim()) return refileTargets.slice(0, 50);
    const terms = refileDebouncedSearch.toLowerCase().split(/\s+/).filter(Boolean);
    const results: string[] = [];
    for (let i = 0; i < refileTargets.length && results.length < 50; i++) {
      const target = refileTargets[i];
      // Match against basename + headings only, not the full directory path
      const parts = target.split('|');
      const basename = parts[0].replace(/^.*\//, '').toLowerCase();
      const headings = parts.slice(1).join(' ').toLowerCase();
      const matchStr = basename + ' ' + headings;
      if (terms.every(term => matchStr.includes(term))) {
        results.push(target);
      }
    }
    return results;
  }, [refileTargets, refileDebouncedSearch]);

  const handleRefile = React.useCallback(async () => {
    if (!refileModalRow || !refileSelected) return;
    const parts = refileSelected.split('|');
    const filename = parts[0];
    const heading = parts.slice(1).join('|');
    const toType = heading ? 'file+headline' : 'file';
    const toId = heading || '';
    try {
      await Db.ODb.refile(refileModalRow.Hash, filename, toId, toType);
      setRecords(prev => prev.filter(r => r.Hash !== refileModalRow.Hash));
      setSelected(prev => prev.filter(id => id !== refileModalRow.Hash));
    } catch (e) {
      console.error('Failed to refile entry:', e);
    }
    setRefileModalOpen(false);
  }, [refileModalRow, refileSelected]);

  const buildQuery = (): string => {
      let qry: string = "";
      let prefix = ""
      if (activeStatus.length > 0) {
        qry += `${prefix}( ${activeStatus.map(s => `IsStatus('${s}')`).join(' || ')} )`;
        prefix = " && ";
      }
      if (activeTags && activeTags.length > 0) {
        let tagsStart = false;
        activeTags.forEach((tag) => {
          if (!tagsStart) {
            qry += `${prefix}( HasTags('${tag}')`;
            tagsStart = true;
          } else {
            qry += ` || HasTags('${tag}')`
          }
        });
        if(tagsStart) {
          qry += ' )'
          prefix = " && ";
        }
      }
      if (activeSearch) {
        if (isWellFormed(activeSearch)) {
          qry += `${prefix}${activeSearch}`;
        } else {
          qry += `${prefix}MatchHeadline('${activeSearch}')`;
        }
        prefix = " && ";
      }
      // The regular expression is added as a clause of its own rather than
      // folded into whatever was typed, so emptying its box takes it away
      // again cleanly. MatchContent is the server function that reads the
      // headline and everything written under it.
      return withoutRecords(withContentMatch(qry, activeContent), showRecords);
  }
  const isWellFormed = (srch: string) => {
    let didFind = false;
    let cnt = 0;
    for (let i = 0; i < srch.length; ++i) {
      let c = srch[i];
      if (c === '(') {
        didFind = true;
        cnt += 1;
      } else if (c === ')') {
        cnt -= 1;
        if (cnt < 0) {
          return false;
        }
        didFind = true;
      }
    }
    return (cnt === 0 && didFind) || !srch;
  }

  const getRecords = async (signal: AbortSignal) => {
    let queryStr: string = buildQuery();
    let baseFilter = '!IsArchived() && IsTodo()';
    if (todoMode === 'noStatus') {
      baseFilter = '!IsArchived() && !IsTodo()';
    } else if (todoMode === 'anything') {
      baseFilter = '!IsArchived()';
    } else if (todoMode === 'projects') {
      // A project is a project whether or not it has a keyword of its own -
      // it is usually its children that carry those - so this does not ask
      // for a todo as well.
      baseFilter = '!IsArchived() && IsProject()';
    }
    console.log("QUERY: ", queryStr);
    var data = await Db.ODb.query(queryStr, false, signal, baseFilter);
    if (signal.aborted) {
      return;
    }
    if (data && Array.isArray(data)) {
      setRecords(data);
      // Accumulate known statuses and tags (never remove, only add)
      setStatusList(prev => {
        const set = new Set(prev);
        data.forEach((r: any) => { if (r.Status) set.add(r.Status); });
        return set.size !== prev.length ? Array.from(set) : prev;
      });
      setTagsList(prev => {
        const set = new Set(prev);
        data.forEach((r: any) => {
          if (r.Tags) r.Tags.forEach((t: any) => set.add(t));
        });
        return set.size !== prev.length ? Array.from(set) : prev;
      });
      setPropsList(prev => {
        const set = new Set(prev);
        data.forEach((r: any) => {
          if (r.Props) Object.keys(r.Props).forEach(k => set.add(k));
        });
        return set.size !== prev.length ? Array.from(set) : prev;
      });
    }
  };
  const tagVals: string[] = [];
  let tagOpts: {[key: string]: string}[] = [];
  tagsList.map((item) => {
    tagOpts.push({"key": item, "value": item, "label": item});
  });
  const handleTagMultiChange = (_event: any, value: any[]) => {
    setActiveTags(value.map((v: any) => typeof v === 'string' ? v : v.label || v.key || ''));
  }
  const handleOptionEqual = (option: any, value: any): boolean => {
    return option['label'] === value['label'];
  }
  const searchTimerRef = React.useRef<ReturnType<typeof setTimeout> | null>(null);
  const handleSearchChange = (val: any) => {
    setSearchText(val.target.value);
    runSearchLater(val.target.value);
  }
  // Typing does not run a query on every keystroke. The delay is on the query
  // rather than on the box, so auto-pairing and the completion list stay
  // immediate while the server is left alone.
  const runSearchLater = (value: string) => {
    if (searchTimerRef.current) {
      clearTimeout(searchTimerRef.current);
    }
    searchTimerRef.current = setTimeout(() => {
      setActiveSearch(value);
    }, 400);
  }
  const contentTimerRef = React.useRef<ReturnType<typeof setTimeout> | null>(null);
  const runContentLater = (value: string) => {
    if (contentTimerRef.current) {
      clearTimeout(contentTimerRef.current);
    }
    // A little longer than the query box: a half-typed regular expression
    // matches a great deal, and searching every body in the database for it is
    // the most expensive thing on this page.
    contentTimerRef.current = setTimeout(() => {
      setActiveContent(value);
    }, 550);
  }


  const renderFilters = () => (
    <React.Fragment>
      <FormControl size="sm">
        <FormLabel>Mode</FormLabel>
        <Select
          size="sm"
          value={todoMode}
          onChange={(_evt: any, value: string | null) => { if (value) setTodoMode(value as any); }}
        >
          <Option value="isTodo">Is Todo</Option>
          <Option value="noStatus">No Status</Option>
          <Option value="anything">Anything</Option>
          <Option value="projects">Projects only</Option>
        </Select>
      </FormControl>

      <FormControl size="sm">
        <FormLabel>Status</FormLabel>
        <Autocomplete
          multiple
          size="sm"
          placeholder="Filter by status"
          options={statusList}
          value={activeStatus}
          onChange={(_evt: any, value: string[]) => { setActiveStatus(value); }}
        />
      </FormControl>

      <FormControl size="sm">
        <FormLabel>Tags</FormLabel>
        <Autocomplete
          multiple
          options={tagOpts}
          onChange={handleTagMultiChange}
          isOptionEqualToValue={handleOptionEqual}
         />
      </FormControl>

      <FormControl size="sm">
        <FormLabel>Properties</FormLabel>
        <Autocomplete
          multiple
          size="sm"
          placeholder="Filter by property"
          options={['Has any property', 'No properties', ...propsList]}
          value={activeProps}
          onChange={(_evt: any, value: string[]) => { setActiveProps(value); }}
        />
      </FormControl>

      {/* Two ways of saying where a result came from. Together rather than
          apart because they answer the same question at two scales: one puts
          the file on every row, the other gathers the rows under it. */}
      <FormControl size="sm">
        <FormLabel>Files</FormLabel>
        <Box sx={{ display: 'flex', gap: 0.5 }}>
          <Tooltip
            size="sm"
            title={showFile
              ? 'The file is under each headline — click to take it off'
              : 'Show which file each heading came from, under its headline'}
          >
            <IconButton
              size="sm"
              variant={showFile ? 'soft' : 'outlined'}
              color={showFile ? 'primary' : 'neutral'}
              onClick={() => setShowFile(!showFile)}
            >
              <FilePathIcon />
            </IconButton>
          </Tooltip>
          <Tooltip
            size="sm"
            title={groupByFile
              ? 'Gathered under each file — click for one flat list'
              : 'Gather the results under the file each came from'}
          >
            <IconButton
              size="sm"
              variant={groupByFile ? 'soft' : 'outlined'}
              color={groupByFile ? 'primary' : 'neutral'}
              onClick={() => setGroupByFile(!groupByFile)}
            >
              <GroupByFileIcon />
            </IconButton>
          </Tooltip>
        </Box>
      </FormControl>

      {/* The address book and the other collections, which are left out of
          these results unless they are asked for. A contact matches "jane" as
          readily as the task about ringing her and is rarely the one being
          looked for; the Contacts and Collections tabs are where they are read.
          The choice is remembered, so somebody who does want them here says so
          once. */}
      <FormControl size="sm">
        <FormLabel>Records</FormLabel>
        <Tooltip
          size="sm"
          title={showRecords
            ? 'Contacts and collections are in these results — click to leave them out'
            : 'Contacts and collections are left out — click to include them'}
        >
          <Button
            size="sm"
            variant={showRecords ? 'soft' : 'outlined'}
            color={showRecords ? 'primary' : 'neutral'}
            onClick={() => setShowRecords(!showRecords)}
            startDecorator={showRecords ? <ContactsIcon /> : <ContactsOffIcon />}
            sx={{ fontWeight: 'md', whiteSpace: 'nowrap' }}
          >
            {showRecords ? 'Included' : 'Excluded'}
          </Button>
        </Tooltip>
      </FormControl>

    </React.Fragment>
  );


/*
      <FormControl size="sm">
        <FormLabel>Customer</FormLabel>
        <Select size="sm" placeholder="All">
          <Option value="all">All</Option>
          <Option value="olivia">Olivia Rhye</Option>
          <Option value="steve">Steve Hampton</Option>
          <Option value="ciaran">Ciaran Murray</Option>
          <Option value="marina">Marina Macdonald</Option>
          <Option value="charles">Charles Fulton</Option>
          <Option value="jay">Jay Hoper</Option>
        </Select>
      </FormControl>


          <!-- <Input size="sm" placeholder="Search" startDecorator={<SearchIcon />} onChange={handleSearchChange} /> -->
*/
  

  React.useEffect(() => {
    const controller = new AbortController();
    const signal = controller.signal;
    getRecords(signal);
    return () => {
      controller.abort();
    }
 }, [activeSearch, activeContent, activeTags, activeStatus, todoMode, showRecords]);

  const filteredRecords = React.useMemo(() => {
    if (activeProps.length === 0) return records;
    const hasAny = activeProps.includes('Has any property');
    const hasNone = activeProps.includes('No properties');
    const specificProps = activeProps.filter(p => p !== 'Has any property' && p !== 'No properties');
    return records.filter(row => {
      const props = row.Props || {};
      const count = Object.keys(props).length;
      // "Has any property" OR "No properties" OR specific prop names — any match passes
      if (hasAny && count > 0) return true;
      if (hasNone && count === 0) return true;
      if (specificProps.length > 0 && specificProps.some(p => p in props)) return true;
      return false;
    });
  }, [records, activeProps]);

  // Reset to first page when filtered results change
  React.useEffect(() => {
    setCurrentPage(0);
  }, [filteredRecords]);
  // Turning grouping on or off rebuilds the list from nothing; page seven of
  // the old one is not page seven of the new one.
  React.useEffect(() => { setCurrentPage(0); }, [groupByFile]);

  // What the table shows, in order, with the file bands in it when the list
  // is grouped.
  //
  // Grouping is a *sort plus headers* rather than a different structure: the
  // rows are the same rows and the columns still line up, so everything the
  // table already does - sorting, selecting, editing in place - keeps working
  // with no second code path.
  //
  // The bands take a slot in the page the way a row does. Paging over rows and
  // drawing the bands around them afterwards is the obvious alternative and is
  // wrong: a folded file has no rows on any page, so its band would have
  // nowhere to be drawn and there would be no way to unfold it.
  type Line = { kind: 'file'; filename: string; count: number } | { kind: 'row'; row: any };

  const displayList = React.useMemo<Line[]>(() => {
    if (!filteredRecords) return [];
    // By the headline, which is what the column the arrow sits in is called.
    // It used to sort on `id`, which a search row does not have - so every
    // comparison came out equal, stableSort kept the order it was given, and
    // the arrow turned round without anything moving.
    const sorted = stableSort(filteredRecords, getComparator(order, 'Headline'));
    if (!groupByFile) return (sorted as any[]).map(row => ({ kind: 'row' as const, row }));

    // Grouped by file, and within a file in whatever order was asked for -
    // sorting by column still means something inside a group.
    const byFile = new Map<string, any[]>();
    for (const row of sorted as any[]) {
      const f = row.Filename || '';
      const got = byFile.get(f);
      if (got) got.push(row); else byFile.set(f, [row]);
    }
    const files = Array.from(byFile.keys()).sort((a, b) => {
      // By the name you read, not by the path: two files called notes.org in
      // different folders still sort together, which is what somebody
      // scanning a list of names expects.
      const an = a.replace(/^.*\//, '');
      const bn = b.replace(/^.*\//, '');
      return an.localeCompare(bn) || a.localeCompare(b);
    });
    const out: Line[] = [];
    for (const f of files) {
      const rows = byFile.get(f) || [];
      out.push({ kind: 'file', filename: f, count: rows.length });
      if (foldedFiles.has(f)) continue;
      for (const row of rows) out.push({ kind: 'row', row });
    }
    return out;
  }, [filteredRecords, order, groupByFile, foldedFiles]);

  const totalPages = Math.max(1, Math.ceil(displayList.length / pageSize));
  const pagedLines = React.useMemo(
    () => displayList.slice(currentPage * pageSize, (currentPage + 1) * pageSize),
    [displayList, currentPage]);

  // A saved search, picked from the command palette. Taken on the way in and
  // put in the box as well as run, so that it can be edited from there - it is
  // a starting point, not a mode.
  const pendingQuery = nav.query;
  React.useEffect(() => {
    if (pendingQuery === null) return;
    nav.tookQuery();
    setSearchText(pendingQuery);
    setActiveSearch(pendingQuery);
    setCurrentPage(0);
  }, [pendingQuery, nav]);

  // Back from the file, to the row they were on.
  //
  // Two steps rather than one, and they cannot be done together: the page has
  // to be put back first, and the row is only in the document once that page
  // has rendered. So the hash is held until it turns up in `pagedLines`, and
  // then it is scrolled to and given a moment of colour - a list of twenty five
  // rows needs saying which one, not just showing it.
  const restore = nav.restore;
  const [flash, setFlash] = React.useState('');
  React.useEffect(() => {
    if (!restore || restore.tab !== 'Search') return;
    nav.tookRestore();
    if (typeof restore.page === 'number') setCurrentPage(restore.page);
    if (restore.hash) setFlash(restore.hash);
  }, [restore]);
  React.useEffect(() => {
    if (flash === '') return;
    const el = document.querySelector(`tr[data-row-hash="${flash}"]`) as HTMLElement | null;
    // Not on this page yet - the results may still be on their way back from
    // the server, so wait rather than give up.
    if (!el) return;
    el.scrollIntoView({ block: 'center', behavior: 'smooth' });
    el.style.transition = 'background-color 0.25s ease';
    el.style.backgroundColor = 'var(--joy-palette-primary-softBg)';
    const off = window.setTimeout(() => { el.style.backgroundColor = ''; }, 1200);
    setFlash('');
    return () => window.clearTimeout(off);
  }, [flash, pagedLines]);

  let keyid = 1;
  const orgOptions = [
    {title: 'IsTask()', value: ''},
    {title: 'MatchHeadline(\'', value: ''}
  ];
  return (
    <React.Fragment>
      <Sheet
        className="SearchAndFilters-mobile"
        sx={{
          display: isMobile ? 'flex' : 'none',
          my: 1,
          gap: 1,
        }}
      >
        <Input
          size="sm"
          placeholder="Search"
          startDecorator={<SearchIcon />}
          sx={{ flexGrow: 1 }}
          value={searchText}
          onChange={handleSearchChange}
        />
        <IconButton
          size="sm"
          variant="outlined"
          color="neutral"
          onClick={() => setOpen(true)}
        >
          <FilterAltIcon />
        </IconButton>
        <Modal open={open} onClose={() => setOpen(false)}>
          <ModalDialog aria-labelledby="filter-modal" layout="fullscreen">
            <ModalClose />
            <Typography id="filter-modal" level="h2">
              Filters
            </Typography>
            <Divider sx={{ my: 2 }} />
            <Sheet sx={{ display: 'flex', flexDirection: 'column', gap: 2 }}>
              <FormControl size="sm">
                <FormLabel>Contents match</FormLabel>
                <Input
                  size="sm"
                  placeholder="a regular expression"
                  startDecorator={<FindInPageIcon />}
                  value={contentText}
                  onChange={(e) => { setContentText(e.target.value); runContentLater(e.target.value); }}
                  sx={{ fontFamily: 'var(--joy-fontFamily-code, monospace)' }}
                />
              </FormControl>
              {renderFilters()}
              <Button color="primary" onClick={() => setOpen(false)}>
                Submit
              </Button>
            </Sheet>
          </ModalDialog>
        </Modal>
      </Sheet>
      <Box
        className="SearchAndFilters-tabletUp"
        sx={{
          borderRadius: 'sm',
          py: 2,
          display: isMobile ? 'none' : 'flex',
          flexWrap: 'wrap',
          gap: 1.5,
          '& > *': {
            minWidth: {
              xs: '120px',
              md: '160px',
            },
          },
        }}
      >
        <FormControl sx={{ flex: 2, minWidth: '260px !important' }} size="sm">
          <FormLabel>Query</FormLabel>
          <QueryBox
            value={searchText}
            onChange={(v) => { setSearchText(v); runSearchLater(v); }}
            placeholder="IsTask() && HasTags('work')"
            startDecorator={<SearchIcon />}
          />
          <FormHelperText sx={{ fontSize: 10 }}>
            An expression, or plain words to match the headline
          </FormHelperText>
        </FormControl>
        <FormControl sx={{ flex: 1 }} size="sm">
          <FormLabel>Contents match</FormLabel>
          <Input
            size="sm"
            placeholder="a regular expression"
            startDecorator={<FindInPageIcon />}
            endDecorator={contentText !== '' ? (
              <IconButton
                size="sm"
                variant="plain"
                color="neutral"
                onClick={() => { setContentText(''); runContentLater(''); }}
              >
                <ClearIcon sx={{ fontSize: 15 }} />
              </IconButton>
            ) : null}
            value={contentText}
            onChange={(e) => { setContentText(e.target.value); runContentLater(e.target.value); }}
            sx={{ fontFamily: 'var(--joy-fontFamily-code, monospace)', fontSize: 13 }}
          />
          <FormHelperText sx={{ fontSize: 10 }}>
            Searches the headline and everything written under it
          </FormHelperText>
        </FormControl>
        {renderFilters()}
      </Box>
      {selected.length > 0 && (
        <Box
          sx={{
            display: 'flex',
            alignItems: 'center',
            gap: 2,
            py: 1,
            px: 2,
            borderRadius: 'sm',
            bgcolor: 'background.level1',
            border: '1px solid',
            borderColor: 'divider',
            flexWrap: 'wrap',
          }}
        >
          <Typography level="body-sm" fontWeight="lg">
            {selected.length} selected
          </Typography>
          <Select
            size="sm"
            placeholder="Change status..."
            onChange={async (_e, newStatus: string | null) => {
              if (!newStatus) return;
              try {
                await Promise.all(
                  selected.map(hash => Db.ODb.changeStatus(hash, newStatus))
                );
                setRecords(prev =>
                  prev.map(r => selected.includes(r.Hash) ? { ...r, Status: newStatus } : r)
                );
                setSelected([]);
              } catch (e) {
                console.error('Failed to bulk change status:', e);
              }
            }}
            sx={{ minWidth: 160 }}
          >
            {statusList.map(status => (
              <Option key={status} value={status}>{status}</Option>
            ))}
          </Select>
          <Button size="sm" variant="outlined" color="neutral" onClick={() => setBulkDateModalOpen(true)}>
            Change date
          </Button>
          <Button size="sm" variant="outlined" color="neutral" onClick={() => { setBulkTagModalOpen(true); setBulkTagModalTags([]); setNewBulkTagInput(''); fetchBulkTags(); }}>
            Change tags
          </Button>
          <Button size="sm" variant="outlined" color="neutral" onClick={() => { setBulkPropModalOpen(true); setNewBulkPropName(''); setNewBulkPropValue(''); }}>
            Change properties
          </Button>
        </Box>
      )}
      {/* The results, as cards, when there is no room for a table.
          Driven by the layout flag rather than by `sm` so that it agrees with
          the rest of the app - and so that the results are drawn at all, which
          before this they were not: the table was `display: none` below `sm`
          and nothing took its place, so the whole panel was blank on a phone. */}
      {isMobile && (
        <Box sx={{ display: 'flex', flexDirection: 'column', gap: 1, overflowY: 'auto', minHeight: 0, flex: 1 }}>
          {pagedLines.length === 0 && (
            <Typography level="body-sm" sx={{ color: 'text.tertiary', p: 2, textAlign: 'center' }}>
              Nothing matched.
            </Typography>
          )}
          {pagedLines.map((line: any, i: number) => line.kind === 'file' ? (
            <FileGroupCard
              key={`gc${i}`}
              filename={line.filename}
              count={line.count}
              folded={foldedFiles.has(line.filename)}
              onFold={() => setFoldedFiles(prev => {
                const next = new Set(prev);
                if (next.has(line.filename)) next.delete(line.filename); else next.add(line.filename);
                return next;
              })}
              onOpen={() => handleJump({ Filename: line.filename, LineNum: 0 })}
            />
          ) : (
            <OrgCard
              key={`c${i}`}
              row={line.row}
              selected={selected}
              setSelected={setSelected}
              showFile={showFile}
              onInspect={handleInspect}
              onJump={handleJump}
              onEdit={handleEdit}
              onStatusPick={handleStatusPick}
              knownTags={allKnownTags}
              onLoadTags={loadAllTags}
              onToggleTag={handleToggleTag}
              onDateSet={handleDateSet}
              onDateRemove={handleDateRemove}
              onDelete={handleDelete}
              onArchive={handleArchive}
              onMove={handleMoveClick}
              onClockIn={handleClockIn}
              onClockOut={handleClockOut}
              clockedInKey={clockedInKey}
              clockStartTime={clockStartTime}
              clockKeyForRow={clockKeyForRow}
              onRename={handleStartRename}
              isEditing={renameHash === line.row.Hash}
              onRenameCommit={handleRenameCommit}
              onRenameCancel={handleRenameCancel}
              onStartEdit={handleStartRename}
              onPropSet={handlePropSet}
              onPropRemove={handlePropRemove}
            />
          ))}
        </Box>
      )}
      <Sheet
        className="SearchContainer"
        variant="outlined"
        sx={{
          display: isMobile ? 'none' : 'initial',
          width: '100%',
          borderRadius: 'sm',
          flexShrink: 1,
          overflow: 'auto',
          minHeight: 0,
        }}
      >
        <Table
          aria-labelledby="tableTitle"
          stickyHeader
          hoverRow
          sx={{
            '--TableCell-headBackground': 'var(--joy-palette-background-level1)',
            '--Table-headerUnderlineThickness': '1px',
            '--TableRow-hoverBackground': 'var(--joy-palette-background-level1)',
            '--TableCell-paddingY': '4px',
            '--TableCell-paddingX': '8px',
          }}
        >
          <thead>
            <OrgEntryHeading records={records} order={order} setOrder={setOrder} selected={selected} setSelected={setSelected}/>
          </thead>
          <tbody>
            { pagedLines.map((line) => {
                keyid += 1;
                if (line.kind === 'file') {
                  return (
                    <FileGroup
                      key={`g${keyid}`}
                      filename={line.filename}
                      count={line.count}
                      folded={foldedFiles.has(line.filename)}
                      onFold={() => setFoldedFiles(prev => {
                        const next = new Set(prev);
                        if (next.has(line.filename)) next.delete(line.filename);
                        else next.add(line.filename);
                        return next;
                      })}
                      onOpen={() => nav.toFile({
                        filename: line.filename,
                        back: {
                          app: 'Search', label: 'Back to search',
                          where: { tab: 'Search', page: currentPage },
                        },
                      })}
                    />
                  );
                }
                const row = line.row;
                return <OrgEntry key={`${keyid}`} row={row} selected={selected} setSelected={setSelected} showFile={showFile} onInspect={handleInspect} onJump={handleJump} onEdit={handleEdit} onStatusPick={handleStatusPick} knownTags={allKnownTags} onLoadTags={loadAllTags} onToggleTag={handleToggleTag} onDateSet={handleDateSet} onDateRemove={handleDateRemove} onDelete={handleDelete} onArchive={handleArchive} onMove={handleMoveClick} onClockIn={handleClockIn} onClockOut={handleClockOut} clockedInKey={clockedInKey} clockStartTime={clockStartTime} clockKeyForRow={clockKeyForRow} onRename={handleStartRename} isEditing={renameHash === row.Hash} onRenameCommit={handleRenameCommit} onRenameCancel={handleRenameCancel} onStartEdit={handleStartRename} onPropSet={handlePropSet} onPropRemove={handlePropRemove} />
            })}
          </tbody>
        </Table>
      </Sheet>
      {/* Paging, on a phone: previous, where you are, next.
          The desktop strip of numbered buttons is eleven targets in a row and
          does not fit; and it was `display: none` below `md` with nothing in
          its place, so a phone could see the first page of results and no
          other. */}
      {isMobile && totalPages > 1 && (
        <Box sx={{ display: 'flex', alignItems: 'center', gap: 1, pt: 1, pb: 0.5 }}>
          <Button
            size="sm"
            variant="outlined"
            color="neutral"
            startDecorator={<KeyboardArrowLeftIcon />}
            disabled={currentPage === 0}
            onClick={() => setCurrentPage(p => p - 1)}
          >
            Prev
          </Button>
          <Typography level="body-xs" sx={{ flex: 1, textAlign: 'center', color: 'text.tertiary' }}>
            {currentPage + 1} / {totalPages}
          </Typography>
          <Button
            size="sm"
            variant="outlined"
            color="neutral"
            endDecorator={<KeyboardArrowRightIcon />}
            disabled={currentPage >= totalPages - 1}
            onClick={() => setCurrentPage(p => p + 1)}
          >
            Next
          </Button>
        </Box>
      )}
      {totalPages > 1 && (
        <Box
          className="Pagination-laptopUp"
          sx={{
            pt: 2,
            gap: 1,
            [`& .${iconButtonClasses.root}`]: { borderRadius: '50%' },
            display: isMobile ? 'none' : { xs: 'none', md: 'flex' },
          }}
        >
          <Button
            size="sm"
            variant="outlined"
            color="neutral"
            startDecorator={<KeyboardArrowLeftIcon />}
            disabled={currentPage === 0}
            onClick={() => setCurrentPage(p => p - 1)}
          >
            Previous
          </Button>

          <Box sx={{ flex: 1 }} />
          {(() => {
            const pages: (number | string)[] = [];
            const maxButtons = 7;
            if (totalPages <= maxButtons) {
              for (let i = 0; i < totalPages; i++) pages.push(i);
            } else {
              pages.push(0);
              if (currentPage > 2) pages.push('…start');
              const start = Math.max(1, currentPage - 1);
              const end = Math.min(totalPages - 2, currentPage + 1);
              for (let i = start; i <= end; i++) pages.push(i);
              if (currentPage < totalPages - 3) pages.push('…end');
              pages.push(totalPages - 1);
            }
            return pages.map((page) =>
              typeof page === 'string' ? (
                <IconButton key={page} size="sm" variant="plain" color="neutral" disabled>
                  …
                </IconButton>
              ) : (
                <IconButton
                  key={page}
                  size="sm"
                  variant={page === currentPage ? 'solid' : 'outlined'}
                  color={page === currentPage ? 'primary' : 'neutral'}
                  onClick={() => setCurrentPage(page)}
                >
                  {page + 1}
                </IconButton>
              )
            );
          })()}
          <Box sx={{ flex: 1 }} />

          <Button
            size="sm"
            variant="outlined"
            color="neutral"
            endDecorator={<KeyboardArrowRightIcon />}
            disabled={currentPage >= totalPages - 1}
            onClick={() => setCurrentPage(p => p + 1)}
          >
            Next
          </Button>
        </Box>
      )}
      {/* Inspect dialog */}
      <Modal open={inspectOpen} onClose={() => setInspectOpen(false)}>
        <ModalDialog sx={{ maxWidth: 720, width: '92vw', maxHeight: '86vh', overflow: 'auto' }}>
          <ModalClose />
          {/* Room on the right for the close button: the date sits at the top
              right of the view and would otherwise be under it. */}
          <Box sx={{ pt: 1, pr: 3 }}>
            <NodeView content={inspectContent} />
          </Box>
        </ModalDialog>
      </Modal>
      {/* Refile modal */}
      <Modal open={refileModalOpen} onClose={() => setRefileModalOpen(false)}>
        <ModalDialog sx={{ maxWidth: 520, width: '90vw', p: 2 }}>
          <ModalClose />
          <Typography level="title-md" sx={{ mb: 0.5 }}>Refile</Typography>
          {refileModalRow && (
            <Typography level="body-sm" sx={{ mb: 1.5, color: 'text.secondary' }}>
              Move: {refileModalRow.Headline}
            </Typography>
          )}
          <Input
            size="sm"
            placeholder="Search targets..."
            autoFocus
            onChange={handleRefileSearchChange}
            sx={{ mb: 1 }}
          />
          <Sheet
            variant="outlined"
            sx={{ borderRadius: 'sm', maxHeight: 300, overflow: 'auto', mb: 1.5 }}
          >
            {refileFiltered.length === 0 ? (
              <Box sx={{ p: 2, textAlign: 'center' }}>
                <Typography level="body-xs" sx={{ color: 'text.tertiary' }}>
                  {refileTargets.length === 0 ? 'Loading...' : 'No matches'}
                </Typography>
              </Box>
            ) : (
              refileFiltered.map((target) => {
                const parts = target.split('|');
                const filename = parts[0].replace(/^.*\//, '');
                const headings = parts.slice(1);
                const isSelected = refileSelected === target;
                return (
                  <Box
                    key={target}
                    onClick={() => setRefileSelected(target)}
                    sx={{
                      px: 1.5, py: 0.75,
                      cursor: 'pointer',
                      bgcolor: isSelected ? 'primary.softBg' : 'transparent',
                      '&:hover': { bgcolor: isSelected ? 'primary.softBg' : 'background.level1' },
                      borderBottom: '1px solid',
                      borderColor: 'divider',
                      '&:last-child': { borderBottom: 'none' },
                    }}
                  >
                    <Typography level="body-xs" sx={{ fontFamily: 'monospace', color: 'text.tertiary', fontSize: '10px' }}>
                      {filename}
                    </Typography>
                    <Typography level="body-sm" sx={{ fontWeight: isSelected ? 'bold' : 'normal' }}>
                      {headings.length > 0 ? headings.join(' > ') : <em>(top of file)</em>}
                    </Typography>
                  </Box>
                );
              })
            )}
          </Sheet>
          {refileSelected && (() => {
            const parts = refileSelected.split('|');
            const filename = parts[0].replace(/^.*\//, '');
            const headings = parts.slice(1);
            return (
              <Typography level="body-xs" sx={{ mb: 1, color: 'text.secondary' }}>
                Target: {filename}{headings.length > 0 ? ` > ${headings.join(' > ')}` : ''}
              </Typography>
            );
          })()}
          <Box sx={{ display: 'flex', gap: 1, justifyContent: 'flex-end' }}>
            <Button size="sm" variant="plain" color="neutral" onClick={() => setRefileModalOpen(false)}>
              Cancel
            </Button>
            <Button size="sm" onClick={handleRefile} disabled={!refileSelected}>
              Refile
            </Button>
          </Box>
        </ModalDialog>
      </Modal>
      {/* Bulk date modal */}
      <Modal open={bulkDateModalOpen} onClose={() => setBulkDateModalOpen(false)}>
        <ModalDialog sx={{ maxWidth: 320, p: 2 }}>
          <ModalClose />
          <Typography level="title-md" sx={{ mb: 1.5 }}>Change Date ({selected.length} items)</Typography>
          <FormControl size="sm" sx={{ mb: 1.5 }}>
            <FormLabel>Type</FormLabel>
            <Select
              size="sm"
              value={bulkDateName}
              onChange={(_e, val) => val && setBulkDateName(val)}
            >
              <Option value="TIMESTAMP">Timestamp</Option>
              <Option value="SCHEDULED">Scheduled</Option>
              <Option value="DEADLINE">Deadline</Option>
              <Option value="CLOSED">Closed</Option>
            </Select>
          </FormControl>
          <FormControl size="sm" sx={{ mb: 1 }}>
            <FormLabel>Date</FormLabel>
            <input
              type="date"
              value={bulkDateValue}
              onChange={(e) => setBulkDateValue(e.target.value)}
              style={{ padding: '6px 8px', borderRadius: 4, border: '1px solid var(--joy-palette-neutral-outlinedBorder)', fontSize: '0.875rem' }}
            />
          </FormControl>
          <FormControl size="sm" sx={{ mb: 1.5 }}>
            <FormLabel>Time</FormLabel>
            <input
              type="time"
              value={bulkDateTime}
              onChange={(e) => setBulkDateTime(e.target.value)}
              style={{ padding: '6px 8px', borderRadius: 4, border: '1px solid var(--joy-palette-neutral-outlinedBorder)', fontSize: '0.875rem' }}
            />
          </FormControl>
          <Box sx={{ display: 'flex', gap: 1, justifyContent: 'flex-end' }}>
            <Button size="sm" variant="soft" color="danger" onClick={handleBulkDateRemove}>Remove</Button>
            <Box sx={{ flex: 1 }} />
            <Button size="sm" variant="plain" color="neutral" onClick={() => setBulkDateModalOpen(false)}>Cancel</Button>
            <Button size="sm" onClick={handleBulkDateChange} disabled={!bulkDateValue}>Apply</Button>
          </Box>
        </ModalDialog>
      </Modal>
      {/* Bulk tags modal */}
      <Modal open={bulkTagModalOpen} onClose={() => setBulkTagModalOpen(false)}>
        <ModalDialog sx={{ maxWidth: 400, p: 2 }}>
          <ModalClose />
          <Typography level="title-md" sx={{ mb: 1 }}>Change Tags ({selected.length} items)</Typography>
          <Typography level="body-xs" sx={{ mb: 1, color: 'text.tertiary' }}>
            Toggling a tag will add/remove it on all selected items.
          </Typography>
          <Box sx={{ display: 'flex', gap: 0.5, mb: 1.5, flexWrap: 'wrap' }}>
            {bulkTagModalTags.map(tag => (
              <Chip
                key={tag}
                size="sm"
                variant="solid"
                color="primary"
                endDecorator={<Typography sx={{ cursor: 'pointer', ml: 0.5, fontSize: '14px', lineHeight: 1 }}>&times;</Typography>}
                onClick={() => handleBulkTagToggle(tag)}
                sx={{ cursor: 'pointer' }}
              >
                {tag}
              </Chip>
            ))}
            {bulkTagModalTags.length === 0 && (
              <Typography level="body-xs" sx={{ color: 'text.tertiary', fontStyle: 'italic' }}>No tags applied this session</Typography>
            )}
          </Box>
          <Divider sx={{ mb: 1.5 }} />
          <Box sx={{ display: 'flex', gap: 1, mb: 1.5 }}>
            <Input
              size="sm"
              placeholder="New tag..."
              value={newBulkTagInput}
              onChange={(e) => setNewBulkTagInput(e.target.value)}
              onKeyDown={(e) => { if (e.key === 'Enter') handleBulkAddNewTag(); }}
              sx={{ flex: 1 }}
            />
            <Button size="sm" onClick={handleBulkAddNewTag} disabled={!newBulkTagInput.trim()}>Add</Button>
          </Box>
          {bulkAllKnownTags.length > 0 && (
            <>
              <Typography level="body-xs" sx={{ mb: 0.5, color: 'text.tertiary' }}>Available tags</Typography>
              <Box sx={{ display: 'flex', gap: 0.5, flexWrap: 'wrap', maxHeight: 200, overflow: 'auto' }}>
                {bulkAllKnownTags.filter(t => !bulkTagModalTags.includes(t)).map(tag => (
                  <Chip
                    key={tag}
                    size="sm"
                    variant="outlined"
                    color="neutral"
                    onClick={() => handleBulkTagToggle(tag)}
                    sx={{ cursor: 'pointer' }}
                  >
                    {tag}
                  </Chip>
                ))}
              </Box>
            </>
          )}
          <Box sx={{ display: 'flex', justifyContent: 'flex-end', mt: 1.5 }}>
            <Button size="sm" variant="plain" color="neutral" onClick={() => setBulkTagModalOpen(false)}>Done</Button>
          </Box>
        </ModalDialog>
      </Modal>
      {/* Bulk properties modal */}
      <Modal open={bulkPropModalOpen} onClose={() => setBulkPropModalOpen(false)}>
        <ModalDialog sx={{ maxWidth: 420, p: 2 }}>
          <ModalClose />
          <Typography level="title-md" sx={{ mb: 1 }}>Change Properties ({selected.length} items)</Typography>
          <Typography level="body-xs" sx={{ mb: 1.5, color: 'text.tertiary' }}>
            Set a property on all selected items, or remove a property from all.
          </Typography>
          {(() => {
            // Collect all prop names across selected items
            const allProps = new Set<string>();
            records.forEach(r => {
              if (selected.includes(r.Hash) && r.Props) {
                Object.keys(r.Props).forEach(k => allProps.add(k));
              }
            });
            const propNames = Array.from(allProps).sort();
            return propNames.length > 0 ? (
              <Box sx={{ mb: 1.5 }}>
                <Typography level="body-xs" sx={{ mb: 0.5, color: 'text.tertiary' }}>Existing properties on selected items</Typography>
                <Box sx={{ display: 'flex', gap: 0.5, flexWrap: 'wrap' }}>
                  {propNames.map(name => (
                    <Chip
                      key={name}
                      size="sm"
                      variant="outlined"
                      color="danger"
                      endDecorator={<Typography sx={{ cursor: 'pointer', ml: 0.5, fontSize: '14px', lineHeight: 1 }}>&times;</Typography>}
                      onClick={() => handleBulkRemoveProp(name)}
                      sx={{ cursor: 'pointer' }}
                    >
                      {name}
                    </Chip>
                  ))}
                </Box>
              </Box>
            ) : null;
          })()}
          <Divider sx={{ mb: 1.5 }} />
          <Typography level="body-xs" sx={{ mb: 0.5, color: 'text.tertiary' }}>Add/set property</Typography>
          <Box sx={{ display: 'flex', gap: 1 }}>
            <Input
              size="sm"
              placeholder="Name"
              value={newBulkPropName}
              onChange={(e) => setNewBulkPropName(e.target.value)}
              sx={{ flex: 1 }}
            />
            <Input
              size="sm"
              placeholder="Value"
              value={newBulkPropValue}
              onChange={(e) => setNewBulkPropValue(e.target.value)}
              onKeyDown={(e) => { if (e.key === 'Enter') handleBulkAddProp(); }}
              sx={{ flex: 1 }}
            />
            <Button size="sm" onClick={handleBulkAddProp} disabled={!newBulkPropName.trim()}>Set</Button>
          </Box>
          <Box sx={{ display: 'flex', justifyContent: 'flex-end', mt: 1.5 }}>
            <Button size="sm" variant="plain" color="neutral" onClick={() => setBulkPropModalOpen(false)}>Done</Button>
          </Box>
        </ModalDialog>
      </Modal>
      {/* Editor modal */}
      {editorRow && (
        <OrgEditor
          open={editorOpen}
          onClose={() => setEditorOpen(false)}
          mode="node"
          hash={editorRow.Hash}
          initialData={editorRow}
          onMutate={handleEditorMutate}
        />
      )}
    </React.Fragment>
  );
}
