// The links tab's own model: what a link is on this side, how the list is
// filtered and gathered, and what a preview of one should be.
//
// The regular expression is the thing worth keeping apart from the component.
// Somebody typing a pattern is typing it one character at a time, and half of
// those characters are not a valid pattern - `[`, `(`, `\` - so "does not
// compile yet" has to be an ordinary state of the box rather than an error, and
// the list has to keep showing something while it is being typed.

export type LinkEntry = {
    Raw: string;
    Desc: string;
    Kind: string;
    Broken: boolean;
    Scheme: string;
    Host: string;
    Service: string;
    Filename: string;
    Heading: string;
    Olp: string[] | null;
    Hash: string;
    Line: number;
    ToFilename: string;
    ToHeadline: string;
    ToHash: string;
    // For a link naming a file on disk: where this server serves it from, and
    // what kind of thing it is. Both resolved server side - see links.go.
    Url: string;
    Media: string;
};

export type LinkService = { Service: string; Count: number };

export type LinkList = {
    Links: LinkEntry[];
    Services: LinkService[];
    Total: number;
};

// What a link is gathered under. Said again here rather than sent per link,
// because the server already sends the pieces and the two rules have to agree:
// the strip's counts come from the server and the bands from here.
export function groupOf(l: LinkEntry): string {
    if (l.Service) return l.Service;
    if (l.Scheme) return l.Scheme;
    return 'org';
}

// What the link says it is, for the row: its description, or the target when it
// was written bare.
export function linkLabel(l: LinkEntry): string {
    const d = (l.Desc || '').trim();
    if (d !== '') return d;
    return l.Raw;
}

// The url an external link points at, or '' when the link stays inside the org
// files. mailto: and friends are urls a browser knows what to do with, but not
// ones to put in a frame.
export function linkUrl(l: LinkEntry): string {
    if (l.Kind !== 'external') return '';
    return l.Raw;
}

// Whether a preview of this link is worth trying in a frame. http(s) only: a
// mailto: in an iframe opens a mail client, and a doi: or an elisp: means
// nothing to a browser at all.
export function canFrame(l: LinkEntry): boolean {
    return l.Kind === 'external' && (l.Scheme === 'http' || l.Scheme === 'https');
}

// A compiled filter, or the reason it is not one yet.
//
// An empty pattern matches everything rather than nothing - it is the state the
// box starts in - and a pattern that does not compile keeps the last thing the
// reader could see rather than emptying the list under them.
export type LinkFilter = { re: RegExp | null; error: string };

export function compileFilter(pattern: string): LinkFilter {
    const p = pattern.trim();
    if (p === '') return { re: null, error: '' };
    try {
        return { re: new RegExp(p, 'i'), error: '' };
    } catch (e: any) {
        return { re: null, error: (e && e.message) || 'That is not a pattern yet.' };
    }
}

// What the pattern is matched against: everything about the link a person might
// remember. The target, what it was written as, where it lives and what it
// points at - because "that link in the meeting notes" and "that jira link" are
// both things somebody types.
export function linkHay(l: LinkEntry): string {
    return [
        l.Raw, l.Desc, l.Host, l.Service, l.Heading,
        l.Filename, l.ToFilename, l.ToHeadline,
        ...(l.Olp || []),
    ].filter(Boolean).join(' ');
}

export function filterLinks(links: LinkEntry[], f: LinkFilter, service: string): LinkEntry[] {
    return links.filter(l => {
        if (service !== '' && groupOf(l) !== service) return false;
        if (f.re === null) return true;
        return f.re.test(linkHay(l));
    });
}

// The file, said the way the other tabs say one.
export function baseName(path: string): string {
    const parts = (path || '').split(/[\\/]/);
    return parts[parts.length - 1] || path;
}

// Where in the org files a link was written, as one line: the heading it is
// under when it has one, and the file and line either way.
export function linkWhere(l: LinkEntry): string {
    const at = `${baseName(l.Filename)}:${l.Line + 1}`;
    return l.Heading ? `${l.Heading} · ${at}` : at;
}

export type LinkGrouping = 'none' | 'service' | 'file';

export type LinkLine =
    | { kind: 'band'; label: string; count: number }
    | { kind: 'link'; link: LinkEntry };

// The list as it is drawn: a flat list, or bands of one kind with their links
// under them. Same shape the code tab's grouping takes - a sort plus headers in
// the same list - so sorting and selecting need no second code path.
export function linkLines(links: LinkEntry[], by: LinkGrouping): LinkLine[] {
    if (by === 'none') return links.map(link => ({ kind: 'link' as const, link }));

    const key = (l: LinkEntry) => by === 'service' ? groupOf(l) : l.Filename;
    const label = (l: LinkEntry) => by === 'service' ? groupOf(l) : baseName(l.Filename);

    const order: string[] = [];
    const groups = new Map<string, LinkEntry[]>();
    for (const l of links) {
        const k = key(l);
        if (!groups.has(k)) { groups.set(k, []); order.push(k); }
        (groups.get(k) as LinkEntry[]).push(l);
    }
    // Biggest band first when grouping by service - that is the question being
    // asked, "where do my links go" - but by name when grouping by file, where
    // the answer is a list of files and their order is the only thing holding
    // it together.
    if (by === 'service') {
        order.sort((a, b) => {
            const d = (groups.get(b) as LinkEntry[]).length - (groups.get(a) as LinkEntry[]).length;
            return d !== 0 ? d : a.localeCompare(b);
        });
    } else {
        order.sort((a, b) => baseName(a).localeCompare(baseName(b)));
    }

    const out: LinkLine[] = [];
    for (const k of order) {
        const ls = groups.get(k) as LinkEntry[];
        out.push({ kind: 'band', label: label(ls[0]), count: ls.length });
        for (const l of ls) out.push({ kind: 'link', link: l });
    }
    return out;
}

// A stable identity for a link, for selecting one and keeping it selected
// across a re-read. A link has no id of its own, so it is named by where it was
// written and what it said - which is what a duplicate of it would differ in.
export function linkKey(l: LinkEntry): string {
    return `${l.Filename}#${l.Line}#${l.Raw}`;
}
