import * as React from 'react';
import Container from '@mui/material/Container';
import Typography from '@mui/material/Typography';
import Box from '@mui/material/Box';
import Link from '@mui/material/Link';
import ProTip from './ProTip';
import { CssVarsProvider } from '@mui/joy/styles';
import CssBaseline from '@mui/joy/CssBaseline';
import Button from '@mui/joy/Button';
import Breadcrumbs from '@mui/joy/Breadcrumbs';
// icons
import HomeRoundedIcon from '@mui/icons-material/HomeRounded';
import ChevronRightRoundedIcon from '@mui/icons-material/ChevronRightRounded';
import DownloadRoundedIcon from '@mui/icons-material/DownloadRounded';

import useScript from './useScript';
import FunctionBar from './components/FunctionBar';
import AppBar from './components/AppBar';
import Search from './components/Search';
import Agenda from './components/Agenda';
import Capture, { isTyping } from './components/Capture';
import Palette, { PaletteActions } from './components/Palette';
import { NavContext, FileJump, Back } from './NavContext';
import Code from './components/Code';
import Links from './components/Links';
import Contacts from './components/Contacts';
import Collections from './components/Collections';
import ClockReport from './components/ClockReport';
import StoredQueries from './components/StoredQueries';
import GanttChart from './components/GanttChart';
import MindMap from './components/MindMap';
import Tables from './components/Tables';
import Kanban from './components/Kanban';
import VoiceNotes from './components/VoiceNotes';
import Files from './components/Files';
import Presentation from './components/Presentation';
import Login from './components/Login';
import OrderList from './components/OrderList';
import Header from './components/Header';
import ColorSchemeToggle from './components/ColorSchemeToggle';
import SettingsMenu from './components/SettingsMenu';
import { AuthProvider, useAuth } from './AuthContext';
import { ChromeContext, Chrome } from './ChromeContext';
import { setSetting } from './settings';
import { useIsMobile } from './useMobile';

const useEnhancedEffect =
  typeof window !== 'undefined' ? React.useLayoutEffect : React.useEffect;


// The application key is a code name - the thing App switches on - and a few of
// them are two words run together. This is what each is called on the page, so
// the title and the breadcrumb read the way the nav entry does.
const APP_TITLES: Record<string, string> = {
  ClockReport: 'Clock Report',
  StoredQueries: 'Saved Queries',
  GanttChart: 'Gantt Chart',
  MindMap: 'Mind Map',
  VoiceNotes: 'Voice Notes',
};

function appTitle(key: string): string {
  return APP_TITLES[key] || key;
}

function Temp() {
  return (<div><Typography>TEST INFO</Typography></div>);
}

function Copyright() {
  return (
    <Typography variant="body2" color="text.secondary" align="center">
      {'Copyright © '}
      <Link color="inherit" href="https://algoriststudios.com/">
        Algorist
      </Link>{' '}
      {new Date().getFullYear()}.
    </Typography>
  );
}



function AppContent() {
  const { isLoggedIn } = useAuth();
  const isMobile = useIsMobile();
  const [activeApp, setActiveApp] = React.useState("Search");
  // The application panel, slid in and out from the button on the function bar.
  //
  // Shut to begin with on a narrow screen. Below `lg` the panel is an
  // off-canvas drawer rather than a thing in the flow, so this flag does not
  // draw it either way - but the button on the rail reads its state, and a
  // button that says the panel is showing when nothing is showing is worse than
  // no button.
  const [navOpen, setNavOpen] = React.useState(!isMobile);
  // The breadcrumbs and the title row, slid up out of the way by whichever
  // application panel offers the button for it. Cleared on the way to another
  // application, because that button leaves with the panel that drew it.
  const [chromeHidden, setChromeHidden] = React.useState(false);
  const chrome: Chrome = React.useMemo(
    () => ({ hidden: chromeHidden, setHidden: setChromeHidden }),
    [chromeHidden],
  );
  React.useEffect(() => { setChromeHidden(false); }, [activeApp]);

  // Where a panel is asking to send the reader. Put down here and picked up by
  // whichever panel the switch mounts - see NavContext.tsx.
  const [jump, setJump] = React.useState<FileJump | null>(null);
  // The way back out of it, and what the panel being returned to asked to be
  // handed when it gets there. Both are put down here for the same reason the
  // jump is: the panel that acts on them is mounted by the switch that sets
  // them, so they have to be waiting rather than delivered.
  const [back, setBack] = React.useState<Back | null>(null);
  const [restore, setRestore] = React.useState<any | null>(null);
  // A search the palette asked for, waiting for the Search tab the same way a
  // jump waits for the Files tab.
  const [pendingQuery, setPendingQuery] = React.useState<string | null>(null);
  const nav = React.useMemo(() => ({
    toFile: (j: FileJump) => { setJump(j); setBack(j.back || null); setActiveApp('Files'); },
    jump,
    took: () => setJump(null),
    back,
    goBack: () => {
      if (!back) return;
      setRestore(back.where === undefined ? null : back.where);
      setBack(null);
      setActiveApp(back.app);
    },
    restore,
    tookRestore: () => setRestore(null),
    query: pendingQuery,
    tookQuery: () => setPendingQuery(null),
  }), [jump, back, restore, pendingQuery]);
  // Leaving by the sidebar rather than by the button drops the way back: a
  // button offering to return you to a search you have since walked away from
  // is a button that lies. A jump sets both in one go, so this does not fire on
  // the way in.
  React.useEffect(() => {
    if (activeApp !== 'Files') setBack(null);
  }, [activeApp]);

  // The command palette, from anywhere.
  //
  // ⌘K / ctrl-K is what a palette is bound to everywhere else, and ctrl-shift-P
  // is what the other half of the world reaches for, so both open it. Unlike
  // `c` below these carry a modifier, so they work while something is being
  // typed into as well - which is exactly when you want to leave for somewhere
  // else.
  const [paletteOpen, setPaletteOpen] = React.useState(false);
  React.useEffect(() => {
    const onKey = (e: KeyboardEvent) => {
      const k = e.key.toLowerCase();
      const palette = ((e.metaKey || e.ctrlKey) && k === 'k')
        || (e.ctrlKey && e.shiftKey && k === 'p');
      if (!palette) return;
      e.preventDefault();
      setPaletteOpen(o => !o);
    };
    window.addEventListener('keydown', onKey);
    return () => window.removeEventListener('keydown', onKey);
  }, []);

  // What the palette is allowed to do. Gathered here because all of it is
  // App's: switching panels, opening the capture dialog, and putting a jump
  // down for whichever panel the switch is about to mount.
  const paletteActions = React.useMemo<PaletteActions>(() => ({
    go: (app: string) => setActiveApp(app),
    capture: (template?: string) => { setCaptureTemplate(template || ''); setCapturing(true); },
    openFile: (filename: string, line?: number, heading?: string) =>
      nav.toFile({
        filename, line, heading,
        // The way back is wherever they were when they opened the palette.
        // There is no `where` to go with it - the palette does not know what
        // that panel was showing, and would be guessing - so this returns to
        // the panel rather than to a place in it.
        back: { app: activeApp, label: `Back to ${appTitle(activeApp).toLowerCase()}` },
      }),
    runQuery: (query: string) => { setPendingQuery(query); setActiveApp('Search'); },
    // A board and a collection are both "which one was I looking at", which is
    // a browser setting the panel reads on the way in - so the palette writes
    // the setting and switches, rather than there being a second way in.
    openBoard: (name: string) => { setSetting('kanbanBoard', name); setActiveApp('Kanban'); },
    openCollection: (name: string) => { setSetting('collection', name); setActiveApp('Collections'); },
  }), [nav, activeApp]);

  // Quick capture, from anywhere.
  //
  // It lives here rather than in a tab because that is the whole point of it:
  // whatever you are reading, `c` files the thing that just occurred to you
  // without taking you off the page. A bare letter is safe because it is only
  // a shortcut when it is not being typed into something - the same rule the
  // agenda's own f/b/t keys follow.
  const [capturing, setCapturing] = React.useState(false);
  // The template the capture dialog should open on, when it was opened by name
  // from the palette rather than by the button.
  const [captureTemplate, setCaptureTemplate] = React.useState('');
  React.useEffect(() => {
    const onKey = (e: KeyboardEvent) => {
      if (capturing) return;
      if (e.metaKey || e.ctrlKey || e.altKey) return;
      if (isTyping(e.target)) return;
      // A dialog of somebody else's is open; c belongs to whatever that is.
      if (document.querySelector('.MuiModal-root')) return;
      if (e.key === 'c' || e.key === 'C') {
        e.preventDefault();
        setCapturing(true);
      }
    };
    window.addEventListener('keydown', onKey);
    return () => window.removeEventListener('keydown', onKey);
  }, [capturing]);

  var application = undefined;
  if (!isLoggedIn) {
    application = <Login />;
  } else if (activeApp === "Authentication") {
    application = <Login />;
  } else if (activeApp === "Agenda") {
    application = <Agenda />;
  } else if (activeApp === "Search") {
    application = <Search />;
  } else if (activeApp === "Code") {
    application = <Code />;
  } else if (activeApp === "Links") {
    application = <Links />;
  } else if (activeApp === "Contacts") {
    application = <Contacts />;
  } else if (activeApp === "Collections") {
    application = <Collections />;
  } else if (activeApp === "ClockReport") {
    application = <ClockReport />;
  } else if (activeApp === "StoredQueries") {
    application = <StoredQueries />;
  } else if (activeApp === "GanttChart") {
    application = <GanttChart />;
  } else if (activeApp === "Tables") {
    application = <Tables />;
  } else if (activeApp === "Kanban") {
    application = <Kanban />;
  } else if (activeApp === "VoiceNotes") {
    application = <VoiceNotes />;
  } else if (activeApp === "Files") {
    application = <Files />;
  } else if (activeApp === "MindMap") {
    application = <MindMap />;
  } else if (activeApp === "Presentation") {
    application = <Presentation />;
  }

  const displayApp = !isLoggedIn ? "Authentication" : activeApp;

  return (
    <Box sx={{ display: 'flex', minHeight: '100dvh' }}>
      <Header title={appTitle(displayApp)} />
      <FunctionBar
        navOpen={navOpen}
        onToggleNav={() => setNavOpen(o => !o)}
        onCapture={() => setCapturing(true)}
        onPalette={() => setPaletteOpen(true)}
      />
      <AppBar onActiveApp={setActiveApp} activeApp={displayApp} open={navOpen} />
      <Box
        component="main"
        className="MainContent"
        sx={{
          // A phone is all content and no margin. 16px each side on a 390px
          // screen is 8% of it; a table or a card row needs that width more
          // than the page needs the air.
          px: {
            xs: 1,
            sm: 2,
            md: 6,
          },
          pt: {
            xs: 'calc(8px + var(--Header-height))',
            sm: 'calc(12px + var(--Header-height))',
            md: 3,
          },
          pb: {
            xs: 1,
            sm: 2,
            md: 3,
          },
          flex: 1,
          display: 'flex',
          flexDirection: 'column',
          minWidth: 0,
          // 100dvh rather than 100vh: on a phone the two are different by the
          // height of the browser's own chrome, and vh is the taller one - so a
          // panel sized to it has its last row under the address bar.
          height: '100dvh',
          gap: isMobile ? 0.5 : 1,
        }}
      >
        {/* The chrome - breadcrumbs, the big title, the page action - which a
            phone does not get at all rather than getting a collapsed version of.
            It is about 120px of a 600px viewport, the title is already in the
            fixed header, and the breadcrumb trail on a one-panel-at-a-time
            screen is a link to the panel you are looking at. `chromeHidden` is
            still honoured above it, because that is a reader asking for the
            room rather than the layout deciding. */}
        {!isMobile && (<>
        {/* The chrome, in a grid row that closes to nothing and takes the
            breadcrumbs and the title with it. Animating grid-template-rows
            rather than a measured height means the rows slide up under their
            own height whatever that turns out to be; the negative margin is
            there to swallow the column gap they leave behind. */}
        <Box
          sx={{
            display: 'grid',
            gridTemplateRows: chromeHidden ? '0fr' : '1fr',
            mb: chromeHidden ? -1 : 0,
            transition: 'grid-template-rows 0.28s ease, margin-bottom 0.28s ease',
          }}
        >
        <Box
          sx={{
            overflow: 'hidden',
            minHeight: 0,
            opacity: chromeHidden ? 0 : 1,
            transform: chromeHidden ? 'translateY(-8px)' : 'none',
            visibility: chromeHidden ? 'hidden' : 'visible',
            transition: `opacity 0.2s ease, transform 0.28s ease, visibility 0s linear ${chromeHidden ? '0.28s' : '0s'}`,
          }}
        >
        <Box sx={{ display: 'flex', alignItems: 'center' }}>
          <Breadcrumbs
            size="sm"
            aria-label="breadcrumbs"
            separator={<ChevronRightRoundedIcon fontSize="small" />}
          >
            <Link
              underline="none"
              color="neutral"
              href="#some-link"
              aria-label="Home"
            >
              <HomeRoundedIcon />
            </Link>
            <Link
              underline="hover"
              color="neutral"
              href="#some-link"
              fontSize={12}
              fontWeight={500}
            >
              Application
            </Link>
            <Typography color="primary" fontWeight={500} fontSize={12}>
              {appTitle(displayApp)}
            </Typography>
          </Breadcrumbs>
          <Box sx={{ ml: 'auto', display: { xs: 'none', md: 'flex' }, gap: 1 }}>
            <ColorSchemeToggle />
            <SettingsMenu />
          </Box>
        </Box>
        <Box
            sx={{
              display: 'flex',
              my: 1,
              gap: 1,
              flexDirection: { xs: 'column', sm: 'row' },
              alignItems: { xs: 'start', sm: 'center' },
              flexWrap: 'wrap',
              justifyContent: 'space-between',
            }}
          >
            <Typography variant="h2">{appTitle(displayApp)}</Typography>
            <Button
              color="primary"
              startDecorator={<DownloadRoundedIcon />}
              size="sm"
            >
              Download PDF
            </Button>
          </Box>
        </Box>
        </Box>
        </>)}
          <ChromeContext.Provider value={chrome}>
            <NavContext.Provider value={nav}>{application}</NavContext.Provider>
          </ChromeContext.Provider>
        </Box>
        <Capture
          open={capturing}
          template={captureTemplate}
          onClose={() => { setCapturing(false); setCaptureTemplate(''); }}
        />
        <Palette
          open={paletteOpen}
          onClose={() => setPaletteOpen(false)}
          actions={paletteActions}
          activeApp={displayApp}
        />
      </Box>
  );
}

export default function App() {
  return (
    <CssVarsProvider disableTransitionOnChange>
      <CssBaseline />
      <AuthProvider>
        <AppContent />
      </AuthProvider>
    </CssVarsProvider>
  );
}
