// The links tab: every link in the org files, and where it goes.
//
// The Code tab is this tab for source blocks and the Tables tab is it for
// tables; this one is for the links, and it exists because a link is the thing
// in an org file with the least to hold on to. A ticket pasted into a heading
// eighteen months ago is findable by grep and by nothing else - you do not
// remember the file, you remember that it was a Jira link about the migration.
//
// So: a regular expression over everything about a link, a strip of the
// services they point at, two ways of gathering them, and - for the one that is
// selected - the far end of the link in a frame beside the list. Reading the
// list tells you where your links go; the frame tells you whether the one you
// found is the one you meant.

import * as React from 'react';
import Box from '@mui/joy/Box';
import Sheet from '@mui/joy/Sheet';
import Input from '@mui/joy/Input';
import Typography from '@mui/joy/Typography';
import Chip from '@mui/joy/Chip';
import IconButton from '@mui/joy/IconButton';
import Button from '@mui/joy/Button';
import Tooltip from '@mui/joy/Tooltip';
import Alert from '@mui/joy/Alert';
import CircularProgress from '@mui/joy/CircularProgress';
import Link from '@mui/joy/Link';
import SearchIcon from '@mui/icons-material/Search';
import RefreshIcon from '@mui/icons-material/Refresh';
import LinkIcon from '@mui/icons-material/LinkOutlined';
import LinkOffIcon from '@mui/icons-material/LinkOffOutlined';
import OpenInNewIcon from '@mui/icons-material/OpenInNewOutlined';
import OpenInFileIcon from '@mui/icons-material/LaunchOutlined';
import ViewListIcon from '@mui/icons-material/ViewListOutlined';
import LayersIcon from '@mui/icons-material/LayersOutlined';
import FolderIcon from '@mui/icons-material/FolderOutlined';
import DescriptionIcon from '@mui/icons-material/DescriptionOutlined';

import { ODb } from '../db';
import {
    LinkEntry, LinkGrouping, compileFilter, filterLinks, linkLines,
    linkLabel, linkWhere, linkKey, canFrame, baseName, groupOf,
} from '../links';
import { useNav } from '../NavContext';
import SplitPane from './SplitPane';
import { useSetting } from '../useSettings';
import { useHtmlTheme } from '../useSettings';
import ThemedHtml from './ThemedHtml';

// A colour per service, stable, so the one you work in is recognisable down the
// list before its name has been read. The same trick the code tab plays with
// languages and the contact avatars play with names.
const HUES = [210, 28, 160, 265, 340, 190, 45, 310, 130, 88];
function serviceHue(name: string): number {
    let h = 0;
    const s = name || 'none';
    for (let i = 0; i < s.length; i++) h = (h * 31 + s.charCodeAt(i)) >>> 0;
    return HUES[h % HUES.length];
}

// The far end of a link that stays inside the org files: the heading it lands
// on, rendered the way the search tab's inspect view renders one.
function OrgPreview({ hash, theme }: { hash: string; theme: string }) {
    const [html, setHtml] = React.useState('');
    const [style, setStyle] = React.useState('');
    const [error, setError] = React.useState('');

    React.useEffect(() => {
        let gone = false;
        setHtml(''); setError('');
        ODb.todoHtml(hash, theme)
            .then(res => {
                if (gone) return;
                setHtml((res && res.Content) || '');
                setStyle((res && res.Style) || '');
            })
            .catch(e => { if (!gone) setError((e && e.message) || 'Could not read that heading.'); });
        return () => { gone = true; };
    }, [hash, theme]);

    if (error !== '') return <Alert size="sm" color="danger" variant="soft">{error}</Alert>;
    if (html === '') return <CircularProgress size="sm" />;
    return <ThemedHtml html={html} style={style} />;
}

export default function Links() {
    const nav = useNav();
    const htmlTheme = useHtmlTheme();
    const [links, setLinks] = React.useState<LinkEntry[]>([]);
    const [total, setTotal] = React.useState(0);
    const [loading, setLoading] = React.useState(true);
    const [error, setError] = React.useState('');
    const [pattern, setPattern] = React.useState('');
    const [service, setService] = React.useState('');
    const [groupBy, setGroupBy] = useSetting('linkGroupBy');
    const [picked, setPicked] = React.useState('');
    // A frame that has been asked for. Kept apart from the selection because a
    // site that refuses to be framed should not stop the row being read.
    const [framed, setFramed] = React.useState('');

    const load = React.useCallback(async () => {
        setLoading(true);
        try {
            const res = await ODb.allLinks();
            setLinks((res && res.Links) || []);
            setTotal((res && res.Total) || 0);
            setError('');
        } catch (e: any) {
            setError((e && e.message) || 'Could not read the links.');
            setLinks([]);
        }
        setLoading(false);
    }, []);

    React.useEffect(() => { load(); }, [load]);

    // Compiled once per keystroke rather than once per link.
    const filter = React.useMemo(() => compileFilter(pattern), [pattern]);
    const shown = React.useMemo(
        () => filterLinks(links, filter, service), [links, filter, service]);
    const lines = React.useMemo(
        () => linkLines(shown, groupBy as LinkGrouping), [shown, groupBy]);

    // The services strip counts the whole database rather than what survived
    // the filter: counting the filtered set would empty the strip the moment a
    // service was picked and leave no way back.
    const services = React.useMemo(() => {
        const counts = new Map<string, number>();
        for (const l of links) counts.set(groupOf(l), (counts.get(groupOf(l)) || 0) + 1);
        return Array.from(counts.entries())
            .map(([Service, Count]) => ({ Service, Count }))
            .sort((a, b) => (b.Count - a.Count) || a.Service.localeCompare(b.Service));
    }, [links]);

    const current = React.useMemo(
        () => shown.find(l => linkKey(l) === picked) || null, [shown, picked]);

    // Picking a row offers the far end; picking a different one drops the frame
    // rather than leaving the last page up beside the new selection.
    const choose = (l: LinkEntry) => {
        const k = linkKey(l);
        setPicked(k);
        setFramed(canFrame(l) ? k : '');
    };

    const jumpTo = (l: LinkEntry) => {
        nav.toFile({
            filename: l.Filename,
            heading: l.Heading || '',
            line: l.Line,
            back: { app: 'Links', label: 'Back to links', where: { tab: 'Links', key: linkKey(l) } },
        });
    };

    // Back from the file, to the link they were reading. Taken at once and
    // applied when the list arrives - see NavContext.tsx.
    const restore = nav.restore;
    const [wanted, setWanted] = React.useState<any | null>(null);
    React.useEffect(() => {
        if (!restore || restore.tab !== 'Links') return;
        nav.tookRestore();
        setWanted(restore.key ? restore : null);
    }, [restore, nav]);
    React.useEffect(() => {
        if (!wanted) return;
        const want = links.find(l => linkKey(l) === wanted.key);
        if (!want) return;
        setPicked(wanted.key);
        setWanted(null);
    }, [wanted, links]);

    const GROUPS: { key: LinkGrouping; icon: React.ReactNode; title: string }[] = [
        { key: 'none', icon: <ViewListIcon />, title: 'One flat list' },
        { key: 'service', icon: <LayersIcon />, title: 'Gather by service' },
        { key: 'file', icon: <FolderIcon />, title: 'Gather by file' },
    ];

    return (
        <SplitPane
            showDetail={current !== null}
            onBack={() => setPicked('')}
            backLabel={current ? linkLabel(current) : undefined}
            listWidth={460}
            list={(
            <Sheet
                variant="outlined"
                sx={{
                    flex: 1, borderRadius: 'sm',
                    display: 'flex', flexDirection: 'column', minHeight: 0,
                }}
            >
                <Box sx={{ p: 1, display: 'flex', gap: 0.5, alignItems: 'center' }}>
                    <Input
                        size="sm"
                        value={pattern}
                        onChange={e => setPattern(e.target.value)}
                        placeholder="A regular expression over every link"
                        startDecorator={<SearchIcon />}
                        error={filter.error !== ''}
                        sx={{ flex: 1 }}
                    />
                    {GROUPS.map(g => (
                        <Tooltip key={g.key} size="sm" title={g.title}>
                            <IconButton
                                size="sm"
                                variant={groupBy === g.key ? 'solid' : 'outlined'}
                                color={groupBy === g.key ? 'primary' : 'neutral'}
                                onClick={() => setGroupBy(g.key)}
                            >
                                {g.icon}
                            </IconButton>
                        </Tooltip>
                    ))}
                    <Tooltip size="sm" title="Read the links again">
                        <IconButton size="sm" variant="outlined" color="neutral" onClick={load}>
                            <RefreshIcon />
                        </IconButton>
                    </Tooltip>
                </Box>

                {/* The services, busiest first */}
                <Box sx={{ px: 1, pb: 0.75, display: 'flex', gap: 0.5, flexWrap: 'wrap', maxHeight: 92, overflowY: 'auto' }}>
                    <Chip
                        size="sm"
                        variant={service === '' ? 'solid' : 'outlined'}
                        color={service === '' ? 'primary' : 'neutral'}
                        onClick={() => setService('')}
                    >
                        Everything
                    </Chip>
                    {services.map(s => (
                        <Chip
                            key={s.Service}
                            size="sm"
                            variant={service === s.Service ? 'solid' : 'outlined'}
                            color={service === s.Service ? 'primary' : 'neutral'}
                            onClick={() => setService(service === s.Service ? '' : s.Service)}
                            startDecorator={
                                <Box sx={{
                                    width: 8, height: 8, borderRadius: '50%',
                                    background: `hsl(${serviceHue(s.Service)} 70% 55%)`,
                                }} />
                            }
                            endDecorator={
                                <Typography level="body-xs" sx={{ color: 'text.tertiary' }}>{s.Count}</Typography>
                            }
                        >
                            {s.Service}
                        </Chip>
                    ))}
                </Box>

                {filter.error !== '' && (
                    <Typography level="body-xs" sx={{ px: 1, pb: 0.5, color: 'warning.plainColor' }}>
                        Not a pattern yet — {filter.error}
                    </Typography>
                )}
                {error !== '' && (
                    <Alert size="sm" color="danger" variant="soft" sx={{ mx: 1, mb: 1 }}>{error}</Alert>
                )}

                <Box sx={{ flex: 1, overflowY: 'auto', minHeight: 0 }}>
                    {loading && <Box sx={{ p: 2 }}><CircularProgress size="sm" /></Box>}
                    {!loading && lines.length === 0 && (
                        <Typography level="body-sm" sx={{ p: 2, color: 'text.tertiary' }}>
                            No link matches that.
                        </Typography>
                    )}
                    {lines.map((line, i) => {
                        if (line.kind === 'band') {
                            return (
                                <Box
                                    key={`b${i}`}
                                    sx={{
                                        px: 1.25, pt: 1.25, pb: 0.5, display: 'flex',
                                        alignItems: 'center', gap: 0.75,
                                        position: 'sticky', top: 0, zIndex: 1,
                                        background: 'var(--joy-palette-background-surface)',
                                    }}
                                >
                                    <Typography
                                        level="body-xs"
                                        sx={{
                                            letterSpacing: '0.08em', textTransform: 'uppercase',
                                            fontWeight: 'lg', color: 'text.tertiary',
                                        }}
                                    >
                                        {line.label}
                                    </Typography>
                                    <Typography level="body-xs" sx={{ color: 'text.tertiary' }}>
                                        {line.count}
                                    </Typography>
                                </Box>
                            );
                        }
                        const l = line.link;
                        const k = linkKey(l);
                        const on = k === picked;
                        return (
                            <Box
                                key={k}
                                onClick={() => choose(l)}
                                sx={{
                                    display: 'flex', gap: 1, alignItems: 'flex-start',
                                    px: 1.25, py: 0.75, cursor: 'pointer', minWidth: 0,
                                    borderLeft: '3px solid',
                                    borderColor: on
                                        ? `hsl(${serviceHue(groupOf(l))} 70% 55%)`
                                        : 'transparent',
                                    background: on ? 'var(--joy-palette-primary-softBg)' : 'transparent',
                                    '&:hover': { background: on ? undefined : 'var(--joy-palette-background-level1)' },
                                }}
                            >
                                <Box sx={{ color: l.Broken ? 'danger.plainColor' : 'text.tertiary', mt: '2px' }}>
                                    {l.Broken ? <LinkOffIcon fontSize="small" /> : <LinkIcon fontSize="small" />}
                                </Box>
                                <Box sx={{ minWidth: 0, flex: 1 }}>
                                    <Typography level="body-sm" noWrap sx={{ fontWeight: on ? 'lg' : 'md' }}>
                                        {linkLabel(l)}
                                    </Typography>
                                    <Typography level="body-xs" noWrap sx={{ color: 'text.tertiary' }}>
                                        {l.Desc ? `${l.Raw} · ` : ''}{linkWhere(l)}
                                    </Typography>
                                </Box>
                                <Tooltip size="sm" title={`Open ${baseName(l.Filename)}:${l.Line + 1} in Files`}>
                                    <IconButton
                                        size="sm"
                                        variant="plain"
                                        color="neutral"
                                        onClick={e => { e.stopPropagation(); jumpTo(l); }}
                                    >
                                        <OpenInFileIcon fontSize="small" />
                                    </IconButton>
                                </Tooltip>
                            </Box>
                        );
                    })}
                </Box>

                <Box sx={{ px: 1.25, py: 0.5, borderTop: '1px solid', borderColor: 'divider' }}>
                    <Typography level="body-xs" sx={{ color: 'text.tertiary' }}>
                        {shown.length === total
                            ? `${total} link${total === 1 ? '' : 's'}`
                            : `${shown.length} of ${total} links`}
                    </Typography>
                </Box>
            </Sheet>
            )}
            detail={(
            <Sheet
                variant="outlined"
                sx={{
                    flex: 1, borderRadius: 'sm', minWidth: 0,
                    display: 'flex', flexDirection: 'column', minHeight: 0,
                }}
            >
                {current === null && (
                    <Box sx={{ flex: 1, display: 'flex', alignItems: 'center', justifyContent: 'center' }}>
                        <Box sx={{ textAlign: 'center', color: 'text.tertiary' }}>
                            <LinkIcon sx={{ fontSize: 48, opacity: 0.4 }} />
                            <Typography level="body-sm">Pick a link to see where it goes.</Typography>
                        </Box>
                    </Box>
                )}
                {current !== null && (
                    <>
                        <Box sx={{ p: 1.25, display: 'flex', gap: 1, alignItems: 'center', minWidth: 0, borderBottom: '1px solid', borderColor: 'divider' }}>
                            <Box sx={{ minWidth: 0, flex: 1 }}>
                                <Typography level="title-sm" noWrap>{linkLabel(current)}</Typography>
                                <Tooltip size="sm" title={current.Raw} placement="bottom-start">
                                    <Typography level="body-xs" noWrap sx={{ color: 'text.tertiary' }}>
                                        {current.Raw}
                                    </Typography>
                                </Tooltip>
                            </Box>
                            {current.Kind === 'external' && (
                                <Button
                                    size="sm"
                                    variant="outlined"
                                    color="neutral"
                                    component="a"
                                    href={current.Raw}
                                    target="_blank"
                                    rel="noreferrer"
                                    startDecorator={<OpenInNewIcon />}
                                >
                                    Open
                                </Button>
                            )}
                            <Tooltip size="sm" title="Open the file this link is written in">
                                <IconButton size="sm" variant="outlined" color="neutral" onClick={() => jumpTo(current)}>
                                    <OpenInFileIcon />
                                </IconButton>
                            </Tooltip>
                        </Box>

                        <Box sx={{ flex: 1, minHeight: 0, display: 'flex', flexDirection: 'column' }}>
                            {/* A page from out there. It may well refuse to be
                                shown in a frame - most of the big ones do - and
                                there is no way to ask first, so the way out sits
                                beside it rather than appearing after it fails. */}
                            {framed === linkKey(current) && canFrame(current) && (
                                <>
                                    <Typography level="body-xs" sx={{ px: 1.25, py: 0.5, color: 'text.tertiary' }}>
                                        Some sites refuse to be shown in a frame — if this stays blank,{' '}
                                        <Link href={current.Raw} target="_blank" rel="noreferrer">open it in a tab</Link>.
                                    </Typography>
                                    <Box
                                        component="iframe"
                                        key={current.Raw}
                                        title="the far end of the link"
                                        src={current.Raw}
                                        // Somebody else's page: let it be a page,
                                        // and nothing more. No same-origin, so it
                                        // cannot reach this one.
                                        sandbox="allow-scripts allow-popups allow-forms"
                                        referrerPolicy="no-referrer"
                                        sx={{ flex: 1, width: '100%', border: 0, minHeight: 0 }}
                                    />
                                </>
                            )}

                            {/* A link at a file beside the notes: a picture, a
                                recording, a pdf. The server worked out where it
                                is and what it is; this just shows it. */}
                            {current.Url !== '' && current.Media === 'image' && (
                                <Box sx={{ p: 1.5, overflow: 'auto', minHeight: 0 }}>
                                    <Box component="img" src={current.Url} alt={current.Raw}
                                        sx={{ maxWidth: '100%', borderRadius: 'sm', display: 'block' }} />
                                </Box>
                            )}
                            {current.Url !== '' && current.Media === 'audio' && (
                                <Box sx={{ p: 1.5 }}>
                                    <Box component="audio" src={current.Url} controls preload="none"
                                        sx={{ width: '100%', height: 36 }} />
                                </Box>
                            )}
                            {current.Url !== '' && current.Media === 'video' && (
                                <Box sx={{ p: 1.5 }}>
                                    <Box component="video" src={current.Url} controls preload="metadata"
                                        sx={{ maxWidth: '100%', borderRadius: 'sm', display: 'block' }} />
                                </Box>
                            )}
                            {current.Url !== '' && current.Media === 'pdf' && (
                                <Box component="iframe" title="the file this link names" src={current.Url}
                                    sx={{ flex: 1, width: '100%', border: 0, minHeight: 0 }} />
                            )}

                            {/* A link that stays inside the org files: the
                                heading it lands on, drawn the way the search
                                tab's inspect view draws one. */}
                            {current.Kind !== 'external' && current.ToHash !== '' && (
                                <Box sx={{ p: 1.5, overflowY: 'auto', minHeight: 0 }}>
                                    <OrgPreview hash={current.ToHash} theme={htmlTheme} />
                                </Box>
                            )}
                            {current.Kind !== 'external' && current.ToHash === '' && current.ToFilename !== '' && (
                                <Box sx={{ p: 2, color: 'text.tertiary' }}>
                                    <DescriptionIcon sx={{ fontSize: 36, opacity: 0.5 }} />
                                    <Typography level="body-sm">
                                        This points at the whole of {baseName(current.ToFilename)}.
                                    </Typography>
                                    <Button
                                        size="sm"
                                        variant="outlined"
                                        color="neutral"
                                        sx={{ mt: 1 }}
                                        startDecorator={<OpenInFileIcon />}
                                        onClick={() => nav.toFile({
                                            filename: current.ToFilename,
                                            back: { app: 'Links', label: 'Back to links', where: { tab: 'Links', key: linkKey(current) } },
                                        })}
                                    >
                                        Open it in Files
                                    </Button>
                                </Box>
                            )}
                            {current.Broken && (
                                <Alert size="sm" color="danger" variant="soft" sx={{ m: 1.5 }}>
                                    This names an org target nothing answers to.
                                </Alert>
                            )}
                            {!canFrame(current) && current.Kind === 'external' && current.Url === '' && (
                                <Box sx={{ p: 2, color: 'text.tertiary' }}>
                                    <Typography level="body-sm">
                                        A {current.Scheme || 'link'} is for something other than a browser to open,
                                        so there is nothing to show here.
                                    </Typography>
                                </Box>
                            )}
                        </Box>
                    </>
                )}
            </Sheet>
            )}
        />
    );
}
