// What a command is matched against: its name, and then the hint, which only
// counts on whole words.
function labelOf(c: Command): string {
    return c.hint ? `${c.name} ${c.hint}` : c.name;
}

// The commands a filter finds, best first.
//
// With nothing typed the order is the one they came in, with whatever was used
// recently lifted to the front - which is what makes the second use of a
// palette faster than the first. With something typed, recency is a nudge
// rather than a rule: it breaks ties between equally good matches and never
// lifts a worse one over a better.
export function rankCommands(cmds: Command[], filter: string, recents: string[] = []): Command[] {
    const rank = new Map<string, number>();
    recents.forEach((id, i) => rank.set(id, recents.length - i));

    const terms = fuzzyTerms(filter);
    if (terms.length === 0) {
        const used = cmds.filter(c => rank.has(c.id))
            .sort((a, b) => (rank.get(b.id) || 0) - (rank.get(a.id) || 0));
        const usedIds = new Set(used.map(c => c.id));
        return [...used, ...cmds.filter(c => !usedIds.has(c.id))];
    }

    const hits: { c: Command; score: number; i: number }[] = [];
    cmds.forEach((c, i) => {
        const score = fuzzyScoreAll(terms, c.name, labelOf(c));
        if (score === null) return;
        hits.push({ c, score: score + Math.min(rank.get(c.id) || 0, 8), i });
    });
    hits.sort((a, b) => (b.score - a.score) || (a.i - b.i));
    return hits.map(h => h.c);
}

// The list as it is drawn: bands of a kind, and the commands under them.
//
// Bands only when nothing has been typed. Once there is a filter the order is
// by how well each matched, and a band drawn round a ranked list would either
// break the ranking or repeat itself all the way down.
export type PaletteLine =
    | { kind: 'band'; label: string }
    | { kind: 'cmd'; cmd: Command };

export function paletteLines(cmds: Command[], filtered: boolean, recentCount: number): PaletteLine[] {
    if (filtered) return cmds.map(cmd => ({ kind: 'cmd' as const, cmd }));
    const out: PaletteLine[] = [];
    let band = '';
    cmds.forEach((cmd, i) => {
        const label = i < recentCount ? 'Recent' : KIND_LABEL[cmd.kind];
        if (label !== band) {
            out.push({ kind: 'band', label });
            band = label;
        }
        out.push({ kind: 'cmd', cmd });
    });
    return out;
}

const RECENTS_KEY = 'worg.palette.recents';
const RECENTS_MAX = 24;

export function loadRecents(): string[] {
    try {
        const raw = window.localStorage.getItem(RECENTS_KEY);
        if (!raw) return [];
        const got = JSON.parse(raw);
        return Array.isArray(got) ? got.filter(x => typeof x === 'string') : [];
    } catch {
        // A browser with storage turned off still gets a working palette; it
        // just does not learn anything between sessions.
        return [];
    }
}

// Newest first, each id once. Headings are not remembered: they are found by
// asking the server what matches, so an id kept here would name a row that has
// since moved, been renamed or gone.
export function noteUse(id: string, kind: CommandKind, recents: string[]): string[] {
    if (kind === 'heading') return recents;
    const next = [id, ...recents.filter(r => r !== id)].slice(0, RECENTS_MAX);
    try {
        window.localStorage.setItem(RECENTS_KEY, JSON.stringify(next));
    } catch {
        // Nothing to do about it, and nothing worth saying.
    }
    return next;
}

// What typed text becomes when it is handed to the server as a headline match.
//
// Three things it has to get right. MatchHeadline takes a regular expression,
// and somebody typing at a palette is not writing one - a `(` half way through
// a word must narrow the list rather than fail the query outright. The whole
// thing arrives inside single quotes, so a quote in the text would close them.
// And it is matched case sensitively, which is never what typing at a palette
// means: `(?i)` is what makes "jane" find "Jane Roe".
export function headlineQuery(text: string): string {
    const safe = text.trim().replace(/[.*+?^${}()|[\]\\]/g, '\\$&').replace(/'/g, '');
    return `MatchHeadline('(?i)${safe}')`;
}
